import type { RawQ } from "../types";
// Tafsir of key passages and central themes of surahs 1–17 (al-Ṭabarī, Ibn Kathīr, al-Qurṭubī). Draft content, needs scholarly review.
export const QS: RawQ[] = [
  { id: "tfl-001", s: "tafsir", g: 1, d: 1, t: ["al-fatiha", "surah-names"], src: "Ibn Kathīr, Tafsīr, introduction to Sūrat al-Fātiḥa", v: "1:2",
    en: ["Which of these is a well-known name of the surah from which the verse shown comes?", ["al-Sabʿ al-Mathānī (the seven oft-repeated)", "al-Zahrāwān (the two radiant ones)", "Sanām al-Qurʾān (the peak of the Quran)", "Qalb al-Qurʾān (the heart of the Quran)"], "Al-Fātiḥa is called Umm al-Kitāb and al-Sabʿ al-Mathānī because its seven verses are repeated in every prayer. Al-Zahrāwān refers to al-Baqara and Āl ʿImrān together."],
    de: ["Welcher dieser Namen ist ein bekannter Name der Sure, aus der der gezeigte Vers stammt?", ["al-Sabʿ al-Mathānī (die sieben Wiederholten)", "al-Zahrāwān (die beiden Leuchtenden)", "Sanām al-Qurʾān (der Gipfel des Koran)", "Qalb al-Qurʾān (das Herz des Koran)"], "Al-Fātiḥa heißt Umm al-Kitāb und al-Sabʿ al-Mathānī, weil ihre sieben Verse in jedem Gebet wiederholt werden. Al-Zahrāwān bezeichnet al-Baqara und Āl ʿImrān zusammen."],
    ar: ["أيّ هذه الأسماء من الأسماء المشهورة للسورة التي منها الآية المعروضة؟", ["السبع المثاني", "الزهراوان", "سنام القرآن", "قلب القرآن"], "تُسمّى الفاتحة أمَّ الكتاب والسبعَ المثاني لأن آياتها السبع تُثنّى وتُكرَّر في كل صلاة، أما الزهراوان فهما البقرة وآل عمران."] },
  { id: "tfl-002", s: "tafsir", g: 1, d: 1, t: ["al-fatiha", "tawhid-in-worship"], src: "Ibn Kathīr, Tafsīr, on 1:5", v: "1:5",
    en: ["What is the central meaning of the verse shown?", ["Worship and the seeking of help are directed to Allah alone", "Allah is the Lord of all the worlds and their sustainer", "Allah alone is the Owner of the Day of Judgement", "The believer asks to be guided to the straight path"], "Placing the object first in this verse expresses exclusivity: worship and reliance belong to Allah alone. Ibn Kathīr notes that the first half is freedom from shirk and the second freedom from relying on one's own strength."],
    de: ["Was ist die zentrale Bedeutung des gezeigten Verses?", ["Anbetung und Bitte um Hilfe richten sich allein an Allah", "Allah ist der Herr der Welten und ihr Erhalter", "Allah allein ist der Herrscher am Tag des Gerichts", "Der Gläubige bittet um Rechtleitung auf den geraden Weg"], "Die Voranstellung des Objekts in diesem Vers drückt Ausschließlichkeit aus: Anbetung und Vertrauen gebühren Allah allein. Ibn Kathīr erklärt, die erste Hälfte sei Lossagung vom Schirk, die zweite Lossagung vom Vertrauen auf die eigene Kraft."],
    ar: ["ما المعنى المحوري للآية المعروضة؟", ["إفراد الله وحده بالعبادة والاستعانة", "أن الله ربّ العالمين ومربّيهم", "أن الله وحده مالك يوم الدين", "سؤال المؤمن الهداية إلى الصراط المستقيم"], "تقديم المفعول في الآية يفيد الحصر، فالعبادة والاستعانة لله وحده. وذكر ابن كثير أن الأول تبرّؤ من الشرك والثاني تبرّؤ من الحول والقوة."] },
  { id: "tfl-003", s: "tafsir", g: 1, d: 1, t: ["al-baqara", "types-of-people"], src: "Ibn Kathīr, Tafsīr, on 2:2", v: "2:2",
    en: ["According to the verse shown, for whom is the Book a guidance?", ["For the God-conscious (al-muttaqūn)", "For the scholars of the People of the Book", "For the Arabs of Mecca specifically", "For those who already memorised it"], "The verse states that the Book, about which there is no doubt, is guidance for the muttaqūn; the following verses describe their qualities."],
    de: ["Für wen ist das Buch nach dem gezeigten Vers eine Rechtleitung?", ["Für die Gottesfürchtigen (al-muttaqūn)", "Für die Gelehrten der Schriftbesitzer", "Ausschließlich für die Araber Mekkas", "Für diejenigen, die es bereits auswendig kennen"], "Der Vers sagt, dass das Buch, an dem kein Zweifel ist, eine Rechtleitung für die muttaqūn ist; die folgenden Verse beschreiben ihre Eigenschaften."],
    ar: ["لمن يكون الكتاب هدًى بحسب الآية المعروضة؟", ["للمتقين", "لعلماء أهل الكتاب", "لعرب مكة خاصة", "لمن حفظه من قبل"], "تخبر الآية أن هذا الكتاب المنزّه عن الشك هادٍ لأهل التقوى، ثم تصف الآيات التالية صفاتهم."] },
  { id: "tfl-004", s: "tafsir", g: 1, d: 1, t: ["ayat-al-kursi", "virtues-of-verses"], src: "Ibn Kathīr, Tafsīr, on 2:255 (hadith of Ubayy ibn Kaʿb in Ṣaḥīḥ Muslim)", v: "2:255",
    en: ["What distinction of the verse shown is established in a hadith in Ṣaḥīḥ Muslim?", ["It is the greatest verse in the Book of Allah", "It is the last verse revealed to the Prophet", "It is the longest verse in the Quran", "It is the first verse revealed in Medina"], "In the hadith of Ubayy ibn Kaʿb in Ṣaḥīḥ Muslim the Prophet asked which verse is the greatest, and Ubayy named Āyat al-Kursī. The longest verse is 2:282."],
    de: ["Welche Auszeichnung des gezeigten Verses ist in einem Hadith in Ṣaḥīḥ Muslim belegt?", ["Er ist der gewaltigste Vers im Buch Allahs", "Er ist der zuletzt offenbarte Vers", "Er ist der längste Vers des Koran", "Er ist der erste in Medina offenbarte Vers"], "Im Hadith des Ubayy ibn Kaʿb in Ṣaḥīḥ Muslim fragte der Prophet, welcher Vers der gewaltigste sei, und Ubayy nannte Āyat al-Kursī. Der längste Vers ist 2:282."],
    ar: ["ما الفضيلة الثابتة للآية المعروضة في حديث في صحيح مسلم؟", ["أنها أعظم آية في كتاب الله", "أنها آخر آية نزلت على النبي", "أنها أطول آية في القرآن", "أنها أول آية نزلت بالمدينة"], "في حديث أُبيّ بن كعب في صحيح مسلم سأله النبي ﷺ عن أعظم آية في كتاب الله فأجاب بأنها آية الكرسي، فأقرّه. أما أطول آية فهي آية الدَّين ٢:٢٨٢."] },
  { id: "tfl-005", s: "tafsir", g: 1, d: 1, t: ["al-baqara", "freedom-of-belief"], src: "Ibn Kathīr, Tafsīr, on 2:256", v: "2:256",
    en: ["Which principle opens the verse shown?", ["There is no compulsion in religion", "Fighting is prescribed for the believers", "Every soul tastes death", "Allah does not forgive shirk"], "The verse begins by stating that there is no compulsion in religion, because right guidance has become clearly distinct from error."],
    de: ["Welcher Grundsatz eröffnet den gezeigten Vers?", ["Es gibt keinen Zwang in der Religion", "Der Kampf ist den Gläubigen vorgeschrieben", "Jede Seele wird den Tod kosten", "Allah vergibt keinen Schirk"], "Der Vers beginnt mit der Aussage, dass es keinen Zwang in der Religion gibt, weil der rechte Weg sich klar vom Irrweg unterschieden hat."],
    ar: ["بأيّ مبدأ تُفتتح الآية المعروضة؟", ["نفي الإكراه في الدين", "فرض القتال على المؤمنين", "أن كل نفس ذائقة الموت", "أن الله لا يغفر الشرك"], "تبدأ الآية بنفي الإكراه في الدين، لأن الرشد قد تبيّن واتّضح من الغيّ."] },
  { id: "tfl-006", s: "tafsir", g: 1, d: 1, t: ["debt-verse", "al-baqara"], src: "Ibn Kathīr, Tafsīr, on 2:282", v: "2:282",
    en: ["The verse shown is the longest verse of the Quran. What is its main subject?", ["Recording debts in writing with witnesses", "The rules of divorce and the waiting period", "The distribution of inheritance shares", "The prohibition of usury (ribā)"], "Known as āyat al-dayn, the verse instructs believers to write down deferred debts, appoint a just scribe and call witnesses."],
    de: ["Der gezeigte Vers ist der längste Vers des Koran. Was ist sein Hauptthema?", ["Das schriftliche Festhalten von Schulden mit Zeugen", "Die Regeln der Scheidung und der Wartezeit", "Die Verteilung der Erbanteile", "Das Verbot des Zinses (ribā)"], "Der als āyat al-dayn bekannte Vers weist die Gläubigen an, befristete Schulden aufzuschreiben, einen gerechten Schreiber zu bestellen und Zeugen hinzuzuziehen."],
    ar: ["الآية المعروضة أطول آية في القرآن، فما موضوعها الرئيس؟", ["توثيق الدَّين بالكتابة والإشهاد", "أحكام الطلاق والعدّة", "توزيع أنصبة الميراث", "تحريم الربا"], "تُعرف بآية الدَّين، وفيها الأمر بكتابة الدين المؤجل على يد كاتب عادل، والإشهاد عليه."] },
  { id: "tfl-007", s: "tafsir", g: 1, d: 1, t: ["fasting-verses", "taqwa"], src: "Ibn Kathīr, Tafsīr, on 2:183", v: "2:183",
    en: ["According to the verse shown, what is the purpose of fasting?", ["That you may attain taqwā (God-consciousness)", "That you may become physically healthy", "That you may feel the hunger of the poor only", "That you may complete the recitation of the Quran"], "The verse ends by naming the goal of fasting: attaining taqwā. It also states that fasting was prescribed for those before you."],
    de: ["Welchen Zweck des Fastens nennt der gezeigte Vers?", ["Dass Sie Gottesfurcht (taqwā) erlangen", "Dass Sie körperlich gesund werden", "Dass Sie nur den Hunger der Armen spüren", "Dass Sie die Rezitation des Koran vollenden"], "Der Vers endet mit dem Ziel des Fastens: der Gottesfurcht (taqwā). Er sagt auch, dass das Fasten bereits den Früheren vorgeschrieben war."],
    ar: ["ما الغاية من الصيام بحسب الآية المعروضة؟", ["تحصيل التقوى", "تحصيل صحة البدن", "الإحساس بجوع الفقراء فحسب", "إتمام ختم القرآن"], "تُختم الآية بذكر غاية الصيام وهي التقوى، وتذكر أنه فُرض على الأمم السابقة أيضًا."] },
  { id: "tfl-008", s: "tafsir", g: 1, d: 1, t: ["fasting-verses", "revelation"], src: "Ibn Kathīr, Tafsīr, on 2:185", v: "2:185",
    en: ["What does the verse shown say about the month of Ramaḍān?", ["It is the month in which the Quran was sent down", "It is the month in which the qibla was changed", "It is the month of the Battle of Uḥud", "It is one of the four sacred months"], "The verse praises Ramaḍān as the month in which the Quran was sent down as guidance for mankind. Ramaḍān is not one of the four sacred months."],
    de: ["Was sagt der gezeigte Vers über den Monat Ramaḍān?", ["In ihm wurde der Koran herabgesandt", "In ihm wurde die Gebetsrichtung geändert", "In ihm fand die Schlacht von Uḥud statt", "Er ist einer der vier heiligen Monate"], "Der Vers rühmt den Ramaḍān als den Monat, in dem der Koran als Rechtleitung für die Menschen herabgesandt wurde. Ramaḍān gehört nicht zu den vier heiligen Monaten."],
    ar: ["ماذا تذكر الآية المعروضة عن شهر رمضان؟", ["أنه الشهر الذي أُنزل فيه القرآن", "أنه الشهر الذي حُوّلت فيه القبلة", "أنه شهر غزوة أحد", "أنه أحد الأشهر الحرم"], "تمدح الآية رمضان بأن القرآن نزل فيه هدايةً للبشر، وليس رمضان من الأشهر الحرم الأربعة."] },
  { id: "tfl-009", s: "tafsir", g: 1, d: 1, t: ["story-of-adam", "iblis"], src: "Ibn Kathīr, Tafsīr, on 2:34", v: "2:34",
    en: ["In the verse shown, who refused to prostrate to Ādam?", ["Iblīs", "Hārūt and Mārūt", "Qābīl", "The angel Jibrīl"], "All the angels prostrated except Iblīs, who refused and was arrogant, and so became one of the disbelievers."],
    de: ["Wer weigerte sich im gezeigten Vers, sich vor Ādam niederzuwerfen?", ["Iblīs", "Hārūt und Mārūt", "Qābīl", "Der Engel Jibrīl"], "Alle Engel warfen sich nieder außer Iblīs; er weigerte sich, war hochmütig und gehörte so zu den Ungläubigen."],
    ar: ["من الذي أبى السجود لآدم في الآية المعروضة؟", ["إبليس", "هاروت وماروت", "قابيل", "جبريل عليه السلام"], "سجد الملائكة كلهم إلا إبليس، فقد امتنع متكبّرًا فصار من أهل الكفر."] },
  { id: "tfl-010", s: "tafsir", g: 1, d: 2, t: ["qibla", "al-baqara"], src: "Ibn Kathīr, Tafsīr, on 2:144", v: "2:144",
    en: ["Towards which direction does the verse shown command the believers to turn their faces in prayer?", ["Towards al-Masjid al-Ḥarām in Mecca", "Towards Bayt al-Maqdis in Jerusalem", "Towards the Prophet's Mosque in Medina", "Towards the east where the sun rises"], "The verse records the change of the qibla from Bayt al-Maqdis to al-Masjid al-Ḥarām, which the Prophet had longed for, looking up towards the sky."],
    de: ["In welche Richtung sollen die Gläubigen nach dem gezeigten Vers ihr Gesicht im Gebet wenden?", ["Zur al-Masjid al-Ḥarām in Mekka", "Zum Bayt al-Maqdis in Jerusalem", "Zur Moschee des Propheten in Medina", "Nach Osten, wo die Sonne aufgeht"], "Der Vers hält die Änderung der Gebetsrichtung vom Bayt al-Maqdis zur al-Masjid al-Ḥarām fest, die der Prophet mit zum Himmel gewandtem Blick ersehnt hatte."],
    ar: ["إلى أيّ جهة تأمر الآية المعروضة المؤمنين أن يولّوا وجوههم في الصلاة؟", ["شطر المسجد الحرام بمكة", "بيت المقدس", "المسجد النبوي بالمدينة", "جهة المشرق"], "تذكر الآية تحويل القبلة من بيت المقدس إلى المسجد الحرام، وكان النبي ﷺ يرفع بصره إلى السماء راجيًا ذلك."] },
  { id: "tfl-011", s: "tafsir", g: 1, d: 1, t: ["al-isra", "night-journey"], src: "Ibn Kathīr, Tafsīr, on 17:1", v: "17:1",
    en: ["Between which two places did the night journey mentioned in the verse shown take place?", ["From al-Masjid al-Ḥarām to al-Masjid al-Aqṣā", "From Mecca to Medina", "From al-Masjid al-Aqṣā to Mount Sinai", "From the cave of Ḥirāʾ to the cave of Thawr"], "The verse opens Sūrat al-Isrāʾ by glorifying Allah who took His servant by night from al-Masjid al-Ḥarām to al-Masjid al-Aqṣā, whose surroundings He blessed."],
    de: ["Zwischen welchen beiden Orten fand die im gezeigten Vers erwähnte Nachtreise statt?", ["Von der al-Masjid al-Ḥarām zur al-Masjid al-Aqṣā", "Von Mekka nach Medina", "Von der al-Masjid al-Aqṣā zum Berg Sinai", "Von der Höhle Ḥirāʾ zur Höhle Thawr"], "Der Vers eröffnet Sūrat al-Isrāʾ mit dem Lobpreis Allahs, der Seinen Diener bei Nacht von der al-Masjid al-Ḥarām zur al-Masjid al-Aqṣā reisen ließ, deren Umgebung Er gesegnet hat."],
    ar: ["بين أيّ مكانين كان الإسراء المذكور في الآية المعروضة؟", ["من المسجد الحرام إلى المسجد الأقصى", "من مكة إلى المدينة", "من المسجد الأقصى إلى طور سيناء", "من غار حراء إلى غار ثور"], "تفتتح الآية سورة الإسراء بتنزيه الله الذي سيّر نبيّه ﷺ في الليل من المسجد الحرام إلى المسجد الأقصى، وقد بارك ما حوله."] },
  { id: "tfl-012", s: "tafsir", g: 1, d: 2, t: ["al-isra-commandments", "parents"], src: "Ibn Kathīr, Tafsīr, on 17:23", v: "17:23",
    en: ["What does the verse shown teach about parents who reach old age?", ["Not even a word of annoyance may be said to them", "They should be placed under the care of relatives", "Obedience to them ends when they grow old", "Kindness to them is recommended but not required"], "Right after the command to worship Allah alone comes excellence towards parents: in their old age one may not show even the slightest sign of irritation, nor rebuke them, but speak to them with noble words."],
    de: ["Was lehrt der gezeigte Vers über Eltern, die ein hohes Alter erreichen?", ["Man darf ihnen nicht einmal ein Wort des Unmuts sagen", "Man soll sie der Obhut von Verwandten übergeben", "Der Gehorsam ihnen gegenüber endet im Alter", "Güte zu ihnen ist empfohlen, aber nicht geboten"], "Unmittelbar nach dem Gebot, Allah allein anzubeten, folgt die Güte zu den Eltern: Im Alter darf man ihnen nicht das geringste Zeichen von Unmut zeigen und sie nicht anfahren, sondern soll ehrerbietig zu ihnen sprechen."],
    ar: ["ماذا تعلّم الآية المعروضة بشأن الوالدين إذا بلغا الكِبَر؟", ["ألّا يُقال لهما أدنى كلمة تضجّر", "أن يُوكَل أمرهما إلى الأقارب", "أن طاعتهما تنتهي عند الكبر", "أن الإحسان إليهما مستحب لا واجب"], "قرن الله الإحسان إلى الوالدين بعبادته وحده، ونهى عن أدنى كلمة تدل على التضجّر وعن نهرهما، وأمر بالقول الكريم لهما."] },
  { id: "tfl-013", s: "tafsir", g: 1, d: 1, t: ["surah-yusuf", "dreams"], src: "Ibn Kathīr, Tafsīr, on 12:4", v: "12:4",
    en: ["What did Yūsuf see in the dream described in the verse shown?", ["Eleven stars, the sun and the moon prostrating to him", "Seven fat cows eaten by seven lean ones", "Himself carrying bread on his head", "Himself pressing grapes into wine"], "Yūsuf saw eleven stars, the sun and the moon prostrating to him; the commentators explain them as his eleven brothers and his parents. The other dreams belong to the king and the two prisoners."],
    de: ["Was sah Yūsuf in dem im gezeigten Vers beschriebenen Traum?", ["Elf Sterne, die Sonne und den Mond, die sich vor ihm niederwarfen", "Sieben fette Kühe, die von sieben mageren gefressen wurden", "Sich selbst, wie er Brot auf dem Kopf trug", "Sich selbst, wie er Trauben zu Wein presste"], "Yūsuf sah elf Sterne, die Sonne und den Mond sich vor ihm niederwerfen; die Kommentatoren deuten sie als seine elf Brüder und seine Eltern. Die anderen Träume gehören dem König und den beiden Gefangenen."],
    ar: ["ماذا رأى يوسف في الرؤيا المذكورة في الآية المعروضة؟", ["أحد عشر نجمًا والشمس والقمر تسجد له", "بقرات سمينة تأكلها بقرات هزيلة", "أنه يحمل الخبز على رأسه", "أنه يستخرج عصير العنب"], "رأى يوسف أحد عشر نجمًا والشمس والقمر تسجد له، وفسّرها المفسرون بإخوته الأحد عشر وأبويه، أما الرؤى الأخرى فللملك وصاحبَي السجن."] },
  { id: "tfl-014", s: "tafsir", g: 1, d: 2, t: ["surah-al-tawba", "surah-names"], src: "al-Qurṭubī, al-Jāmiʿ li-Aḥkām al-Qurʾān, introduction to Sūrat al-Tawba", v: "9:1",
    en: ["What is unique about the surah from which the verse shown comes?", ["It is the only surah not preceded by the basmala", "It is the only surah named after a woman", "It is the only surah revealed entirely at night", "It is the only surah without any Medinan verse"], "Sūrat al-Tawba, also called Barāʾa, is the only surah in the muṣḥaf that does not begin with the basmala. The surah named after a woman is Maryam."],
    de: ["Was ist das Besondere an der Sure, aus der der gezeigte Vers stammt?", ["Sie ist die einzige Sure ohne vorangestellte Basmala", "Sie ist die einzige nach einer Frau benannte Sure", "Sie ist die einzige ganz bei Nacht offenbarte Sure", "Sie ist die einzige Sure ohne medinensischen Vers"], "Sūrat al-Tawba, auch Barāʾa genannt, ist die einzige Sure im Muṣḥaf, die nicht mit der Basmala beginnt. Die nach einer Frau benannte Sure ist Maryam."],
    ar: ["ما الذي تنفرد به السورة التي منها الآية المعروضة؟", ["أنها السورة الوحيدة التي لم تُكتب البسملة في أولها", "أنها السورة الوحيدة المسمّاة باسم امرأة", "أنها السورة الوحيدة التي نزلت كلها ليلًا", "أنها السورة الوحيدة التي ليس فيها آية مدنية"], "سورة التوبة وتُسمّى براءة هي السورة الوحيدة في المصحف التي لم تُفتتح بالبسملة، أما السورة المسمّاة باسم امرأة فهي سورة مريم."] },
  { id: "tfl-015", s: "tafsir", g: 1, d: 2, t: ["surah-al-tawba", "hijra"], src: "Ibn Kathīr, Tafsīr, on 9:40", v: "9:40",
    en: ["Who is the 'second of two' with the Prophet in the cave mentioned in the verse shown?", ["Abū Bakr al-Ṣiddīq", "ʿAlī ibn Abī Ṭālib", "ʿUmar ibn al-Khaṭṭāb", "Zayd ibn Ḥāritha"], "The verse refers to the hijra, when the Prophet and Abū Bakr hid in the cave of Thawr; the Prophet reassured his companion that Allah was with them."],
    de: ["Wer ist der „Zweite von zweien“ mit dem Propheten in der Höhle, von der der gezeigte Vers spricht?", ["Abū Bakr al-Ṣiddīq", "ʿAlī ibn Abī Ṭālib", "ʿUmar ibn al-Khaṭṭāb", "Zayd ibn Ḥāritha"], "Der Vers bezieht sich auf die Hidschra, als der Prophet und Abū Bakr sich in der Höhle Thawr verbargen; der Prophet beruhigte seinen Gefährten, dass Allah mit ihnen sei."],
    ar: ["من هو «ثاني اثنين» مع النبي ﷺ في الغار المذكور في الآية المعروضة؟", ["أبو بكر الصديق", "علي بن أبي طالب", "عمر بن الخطاب", "زيد بن حارثة"], "تشير الآية إلى الهجرة حين اختبأ النبي ﷺ وأبو بكر في غار ثور، فطمأن النبيُّ صاحبَه بأن الله معهما."] },
  { id: "tfl-016", s: "tafsir", g: 1, d: 2, t: ["surah-al-nahl", "ethics"], src: "Ibn Kathīr, Tafsīr, on 16:90", v: "16:90",
    en: ["Which three things does the verse shown command?", ["Justice, excellence (iḥsān) and giving to relatives", "Prayer, fasting and pilgrimage", "Patience, gratitude and repentance", "Charity, jihad and enjoining good"], "Allah commands ʿadl, iḥsān and giving to kin, and forbids indecency (faḥshāʾ), wrongdoing (munkar) and transgression (baghy)."],
    de: ["Welche drei Dinge gebietet der gezeigte Vers?", ["Gerechtigkeit, vortreffliches Handeln (iḥsān) und Gaben an Verwandte", "Gebet, Fasten und Pilgerfahrt", "Geduld, Dankbarkeit und Reue", "Almosen, Dschihad und das Gebieten des Guten"], "Allah gebietet ʿadl, iḥsān und das Geben an die Verwandten und verbietet Schändlichkeit (faḥshāʾ), Verwerfliches (munkar) und Übertretung (baghy)."],
    ar: ["ما الأمور الثلاثة التي تأمر بها الآية المعروضة؟", ["العدل والإحسان والعطاء للأقارب", "الصلاة والصيام والحج", "الصبر والشكر والتوبة", "الصدقة والجهاد والأمر بالمعروف"], "تأمر الآية بالعدل والإحسان والعطاء للأقارب، وتنهى عن الفواحش والمنكرات والعدوان على الناس."] },
  { id: "tfl-017", s: "tafsir", g: 1, d: 2, t: ["surah-al-rad", "sunan-of-allah"], src: "Ibn Kathīr, Tafsīr, on 13:11", v: "13:11",
    en: ["Which divine law (sunna) is stated in the verse shown?", ["Allah does not change a people's condition until they change what is in themselves", "Allah sends a messenger to every nation in its own language", "Every community has an appointed term it cannot delay", "Allah tests people with fear, hunger and loss of wealth"], "The verse states that Allah does not alter what a people are in until they alter what is within themselves; Ibn Kathīr links it to blessings removed through disobedience."],
    de: ["Welches göttliche Gesetz (sunna) nennt der gezeigte Vers?", ["Allah ändert den Zustand eines Volkes nicht, bis es sich selbst ändert", "Allah sendet jedem Volk einen Gesandten in dessen Sprache", "Jede Gemeinschaft hat eine Frist, die sie nicht aufschieben kann", "Allah prüft die Menschen mit Furcht, Hunger und Verlust an Besitz"], "Der Vers sagt, dass Allah den Zustand eines Volkes nicht ändert, bis es das ändert, was in ihm selbst ist; Ibn Kathīr bezieht dies auf Gnaden, die durch Ungehorsam verloren gehen."],
    ar: ["ما السنة الإلهية المذكورة في الآية المعروضة؟", ["أن الله لا يبدّل حال قوم حتى يبدّلوا هم ما في نفوسهم", "أن الله يبعث إلى كل أمة رسولًا يتكلم بلغتها", "أن لكل أمة أجلًا محددًا لا تؤخّره", "أن الله يختبر الناس بالخوف والجوع وذهاب الأموال"], "تقرّر الآية أن تبديل حال القوم مرتبط بتبديلهم ما في نفوسهم، وربطها ابن كثير بزوال النعم بسبب المعاصي."] },
  { id: "tfl-018", s: "tafsir", g: 1, d: 1, t: ["surah-ibrahim", "gratitude"], src: "Ibn Kathīr, Tafsīr, on 14:7", v: "14:7",
    en: ["What does the verse shown promise to those who are grateful?", ["Allah will increase them in His favour", "Allah will forgive all their past sins", "Allah will grant them a long life", "Allah will protect them from every trial"], "The verse promises increase for gratitude and warns that ingratitude brings severe punishment."],
    de: ["Was verspricht der gezeigte Vers den Dankbaren?", ["Allah wird ihnen mehr von Seiner Gunst geben", "Allah wird ihnen alle früheren Sünden vergeben", "Allah wird ihnen ein langes Leben schenken", "Allah wird sie vor jeder Prüfung bewahren"], "Der Vers verspricht den Dankbaren Mehrung und warnt, dass Undankbarkeit eine strenge Strafe nach sich zieht."],
    ar: ["ماذا تَعِد الآية المعروضة الشاكرين؟", ["أن يزيدهم الله من نعمته", "أن يغفر لهم كل ذنوبهم السابقة", "أن يطيل أعمارهم", "أن يحميهم من كل ابتلاء"], "تعد الآية الشاكرين بالزيادة، وتتوعّد الكافرين بالنعمة بعذاب شديد."] },
  { id: "tfl-019", s: "tafsir", g: 1, d: 1, t: ["surah-al-hijr", "preservation-of-quran"], src: "Ibn Kathīr, Tafsīr, on 15:9", v: "15:9",
    en: ["What does Allah guarantee in the verse shown?", ["That He Himself preserves the revealed Reminder", "That every prophet will be protected from harm", "That the Kaʿba will never be destroyed", "That the believers will always be the majority"], "Allah states that He sent down the Reminder (the Quran) and that He is its guardian, protecting it from alteration."],
    de: ["Was garantiert Allah im gezeigten Vers?", ["Dass Er selbst die herabgesandte Ermahnung bewahrt", "Dass jeder Prophet vor Schaden geschützt wird", "Dass die Kaʿba niemals zerstört wird", "Dass die Gläubigen immer die Mehrheit sein werden"], "Allah sagt, dass Er die Ermahnung (den Koran) herabgesandt hat und ihr Hüter ist, der sie vor Veränderung bewahrt."],
    ar: ["بماذا تكفّل الله في الآية المعروضة؟", ["بحفظ القرآن الذي أنزله", "بحماية كل نبي من الأذى", "بألا تُهدم الكعبة أبدًا", "بأن يكون المؤمنون دائمًا الأكثرية"], "يخبر الله أنه هو الذي أنزل القرآن وأنه يتولّى حفظه من التبديل والتحريف."] },
  { id: "tfl-020", s: "tafsir", g: 1, d: 1, t: ["end-of-baqara", "divine-mercy"], src: "Ibn Kathīr, Tafsīr, on 2:286", v: "2:286",
    en: ["Which principle of Allah's law does the verse shown begin with?", ["Allah does not burden a soul beyond its capacity", "Every soul will be paid in full for its deeds", "No bearer of burdens bears the burden of another", "Allah loves those who repent often"], "The verse begins with the principle that Allah charges no soul with more than it can bear; it then teaches the believers a comprehensive supplication."],
    de: ["Mit welchem Grundsatz der göttlichen Gesetzgebung beginnt der gezeigte Vers?", ["Allah belastet keine Seele über ihr Vermögen hinaus", "Jede Seele erhält den vollen Lohn ihrer Taten", "Keine Seele trägt die Last einer anderen", "Allah liebt die, die oft bereuen"], "Der Vers beginnt mit dem Grundsatz, dass Allah keiner Seele mehr auferlegt, als sie tragen kann; danach lehrt er die Gläubigen ein umfassendes Bittgebet."],
    ar: ["بأيّ قاعدة من قواعد التشريع تبدأ الآية المعروضة؟", ["أن التكليف لا يتجاوز طاقة النفس", "أن كل نفس تُجزى بعملها كاملًا", "أن أحدًا لا يحمل ذنب غيره", "أن الله يحب كثيري التوبة"], "تبدأ الآية بقاعدة أن الله لا يكلّف نفسًا إلا ما تطيقه، ثم تعلّم المؤمنين دعاءً جامعًا."] },
  { id: "tfl-021", s: "tafsir", g: 1, d: 2, t: ["surah-hud", "story-of-nuh"], src: "Ibn Kathīr, Tafsīr, on 11:42–43", v: "11:42",
    en: ["In the passage of the verse shown, what did Nūḥ's son do when his father called him to board the ark?", ["He refused and said he would take refuge on a mountain", "He boarded the ark with his wife", "He asked for time to call his brothers", "He went to warn the people of the city"], "Nūḥ called his son to embark, but the son said he would seek refuge on a mountain to protect him from the water; the waves came between them and he was among the drowned."],
    de: ["Was tat Nūḥs Sohn in der Passage des gezeigten Verses, als sein Vater ihn rief, die Arche zu besteigen?", ["Er weigerte sich und wollte Zuflucht auf einem Berg suchen", "Er bestieg die Arche mit seiner Frau", "Er bat um Zeit, um seine Brüder zu holen", "Er ging, um die Leute der Stadt zu warnen"], "Nūḥ rief seinen Sohn, einzusteigen, doch dieser sagte, er werde auf einem Berg Schutz vor dem Wasser suchen; die Wogen trennten sie, und er war unter den Ertrunkenen."],
    ar: ["ماذا فعل ابن نوح في سياق الآية المعروضة حين دعاه أبوه إلى ركوب السفينة؟", ["رفض وقال إنه يلجأ إلى جبل يحميه من الماء", "ركب السفينة مع زوجته", "استمهل ليدعو إخوته", "ذهب لينذر أهل المدينة"], "دعا نوحٌ ابنه إلى الركوب فزعم أن جبلًا سيحميه من الماء، ففرّق الموج بينهما وهلك مع الغارقين."] },
  { id: "tfl-022", s: "tafsir", g: 1, d: 2, t: ["surah-al-anfal", "badr"], src: "Ibn Kathīr, Tafsīr, on 8:1", v: "8:1",
    en: ["What is the 'anfāl' about which the Companions asked in the verse shown?", ["The spoils of war, after the Battle of Badr", "The voluntary night prayers", "The extra shares of inheritance", "The gifts sent by foreign kings"], "Anfāl here means spoils of war; the Companions differed about the spoils of Badr, and the verse assigned their disposal to Allah and His Messenger and called for setting relations right."],
    de: ["Was sind die „anfāl“, nach denen die Gefährten im gezeigten Vers fragten?", ["Die Kriegsbeute, nach der Schlacht von Badr", "Die freiwilligen Nachtgebete", "Die zusätzlichen Erbanteile", "Die Geschenke fremder Könige"], "Anfāl bedeutet hier Kriegsbeute; die Gefährten waren über die Beute von Badr uneins, und der Vers wies die Verfügung darüber Allah und Seinem Gesandten zu und rief zur Versöhnung auf."],
    ar: ["ما «الأنفال» التي سأل عنها الصحابة في الآية المعروضة؟", ["الغنائم، وذلك بعد غزوة بدر", "صلاة النافلة في الليل", "الزيادات في أنصبة الميراث", "الهدايا التي يرسلها الملوك"], "الأنفال هنا الغنائم، اختلف الصحابة في غنائم بدر فجعل الله حكمها لله والرسول وأمرهم بالصلح فيما بينهم."] },
  { id: "tfl-023", s: "tafsir", g: 2, d: 3, t: ["al-fatiha", "hadith-in-tafsir"], src: "Ibn Kathīr, Tafsīr, on 1:7 (hadith of ʿAdī ibn Ḥātim in Jāmiʿ al-Tirmidhī)", v: "1:7",
    en: ["In the hadith of ʿAdī ibn Ḥātim that Ibn Kathīr cites on the verse shown, who are meant by 'those who earned anger' and 'those astray'?", ["The Jews and the Christians respectively", "The hypocrites and the polytheists respectively", "Iblīs and his followers respectively", "The people of ʿĀd and Thamūd respectively"], "Ibn Kathīr cites the hadith in al-Tirmidhī identifying the first group with the Jews and the second with the Christians, adding that the first knew the truth and abandoned it while the second lacked knowledge. The meaning extends to all who share these traits."],
    de: ["Wer ist nach dem Hadith des ʿAdī ibn Ḥātim, den Ibn Kathīr zum gezeigten Vers anführt, mit „denen, die Zorn erregt haben“ und „den Irregehenden“ gemeint?", ["Die Juden bzw. die Christen", "Die Heuchler bzw. die Götzendiener", "Iblīs bzw. seine Anhänger", "Das Volk ʿĀd bzw. das Volk Thamūd"], "Ibn Kathīr führt den Hadith bei al-Tirmidhī an, der die erste Gruppe mit den Juden und die zweite mit den Christen gleichsetzt; die ersten kannten die Wahrheit und verließen sie, den zweiten fehlte das Wissen. Die Bedeutung erstreckt sich auf alle, die diese Merkmale teilen."],
    ar: ["في حديث عديّ بن حاتم الذي أورده ابن كثير عند الآية المعروضة، من المراد بالمغضوب عليهم والضالين؟", ["اليهود والنصارى على الترتيب", "المنافقون والمشركون على الترتيب", "إبليس وأتباعه على الترتيب", "قوم عاد وثمود على الترتيب"], "أورد ابن كثير حديث الترمذي في تفسير المغضوب عليهم باليهود والضالين بالنصارى، وبيّن أن الأولين عرفوا الحق وتركوه والآخرين فقدوا العلم، ويدخل في ذلك كل من شاركهم في صفتهم."] },
  { id: "tfl-024", s: "tafsir", g: 2, d: 2, t: ["types-of-people", "al-baqara"], src: "Ibn Kathīr, Tafsīr, on 2:3", v: "2:3",
    en: ["Which qualities of the God-conscious are listed in the verse shown?", ["Belief in the unseen, establishing prayer and spending from provision", "Fasting, pilgrimage and fighting in Allah's way", "Night prayer, seclusion and frequent fasting", "Truthfulness, patience and keeping promises"], "The verse describes the muttaqūn as those who believe in the unseen (al-ghayb), establish the prayer and spend from what Allah has provided them."],
    de: ["Welche Eigenschaften der Gottesfürchtigen nennt der gezeigte Vers?", ["Glaube an das Verborgene, Verrichten des Gebets und Spenden vom Versorgten", "Fasten, Pilgerfahrt und Einsatz auf Allahs Weg", "Nachtgebet, Zurückgezogenheit und häufiges Fasten", "Wahrhaftigkeit, Geduld und das Halten von Versprechen"], "Der Vers beschreibt die muttaqūn als jene, die an das Verborgene (al-ghayb) glauben, das Gebet verrichten und von dem ausgeben, womit Allah sie versorgt hat."],
    ar: ["ما صفات المتقين المذكورة في الآية المعروضة؟", ["الإيمان بالغيب وإقامة الصلاة والإنفاق مما رزقهم الله", "الصيام والحج والجهاد في سبيل الله", "قيام الليل والعزلة وكثرة الصيام", "الصدق والصبر والوفاء بالعهد"], "تصف الآية المتقين بثلاث صفات: التصديق بالغيب، وأداء الصلاة على وجهها، والإنفاق من رزق الله."] },
  { id: "tfl-025", s: "tafsir", g: 2, d: 2, t: ["types-of-people", "hypocrisy"], src: "Ibn Kathīr, Tafsīr, on 2:17", v: "2:17",
    en: ["Whom does the parable of the man who kindled a fire, in the verse shown, describe?", ["The hypocrites", "The People of the Book", "The repentant believers", "The jinn who listened to the Quran"], "The verse is the first of two parables for the hypocrites: they gained some light by outwardly accepting faith, then Allah took away their light and left them in darkness. The second parable, of the rainstorm, follows in 2:19."],
    de: ["Wen beschreibt das Gleichnis vom Mann, der ein Feuer entfachte, im gezeigten Vers?", ["Die Heuchler", "Die Schriftbesitzer", "Die reuigen Gläubigen", "Die Dschinn, die dem Koran zuhörten"], "Der Vers ist das erste von zwei Gleichnissen über die Heuchler: Durch die äußere Annahme des Glaubens erhielten sie etwas Licht, dann nahm Allah ihr Licht weg und ließ sie in Finsternis. Das zweite Gleichnis vom Platzregen folgt in 2:19."],
    ar: ["من الذين يصفهم مثل الذي استوقد نارًا في الآية المعروضة؟", ["المنافقون", "أهل الكتاب", "المؤمنون التائبون", "الجن الذين استمعوا القرآن"], "هذا أول مثلين ضربهما الله للمنافقين: استضاؤوا بإظهار الإيمان ثم ذهب الله بنورهم وتركهم في ظلمات، والمثل الثاني وهو الصيّب يأتي في ٢:١٩."] },
  { id: "tfl-026", s: "tafsir", g: 2, d: 2, t: ["story-of-adam", "knowledge"], src: "Ibn Kathīr, Tafsīr, on 2:31", v: "2:31",
    en: ["What did Allah teach Ādam according to the verse shown, and what did it demonstrate?", ["The names of all things, showing his merit through knowledge", "The art of building, showing his power over the earth", "The language of the angels, showing his equality with them", "The secrets of the unseen, showing his prophethood"], "Allah taught Ādam the names of all things and then presented them to the angels, who could not name them; this showed Ādam's superiority through knowledge."],
    de: ["Was lehrte Allah Ādam nach dem gezeigten Vers, und was wurde dadurch gezeigt?", ["Die Namen aller Dinge, was seinen Vorzug durch Wissen zeigte", "Die Baukunst, was seine Macht über die Erde zeigte", "Die Sprache der Engel, was seine Gleichheit mit ihnen zeigte", "Die Geheimnisse des Verborgenen, was sein Prophetentum zeigte"], "Allah lehrte Ādam die Namen aller Dinge und legte sie dann den Engeln vor, die sie nicht benennen konnten; so wurde Ādams Vorrang durch Wissen deutlich."],
    ar: ["ماذا علّم الله آدم في الآية المعروضة، وما الذي دلّ عليه ذلك؟", ["الأسماء كلها، دلالةً على فضله بالعلم", "صنعة البناء، دلالةً على سلطانه في الأرض", "لغة الملائكة، دلالةً على مساواته لهم", "أسرار الغيب، دلالةً على نبوّته"], "علّم الله آدم الأسماء كلها ثم عرضهم على الملائكة فعجزوا عن ذكرها، فظهر فضل آدم بالعلم."] },
  { id: "tfl-027", s: "tafsir", g: 2, d: 3, t: ["qibla", "ummah-wasat"], src: "Ibn Kathīr, Tafsīr, on 2:143 (hadith of Abū Saʿīd al-Khudrī in Ṣaḥīḥ al-Bukhārī)", v: "2:143", w: 4,
    en: ["How is the highlighted word explained in a hadith in Ṣaḥīḥ al-Bukhārī?", ["As 'just' (ʿadl)", "As 'small in number'", "As 'located in the middle of the earth'", "As 'moderate in wealth'"], "In the hadith of Abū Saʿīd on Nūḥ's people being asked whether he conveyed the message, the Prophet explained wasaṭ as ʿadl. Ibn Kathīr adds that it also means the best and most excellent."],
    de: ["Wie wird das hervorgehobene Wort in einem Hadith in Ṣaḥīḥ al-Bukhārī erklärt?", ["Als „gerecht“ (ʿadl)", "Als „gering an Zahl“", "Als „in der Mitte der Erde gelegen“", "Als „mäßig an Vermögen“"], "Im Hadith des Abū Saʿīd über die Befragung des Volkes Nūḥs, ob er die Botschaft überbracht habe, erklärte der Prophet wasaṭ als ʿadl. Ibn Kathīr fügt hinzu, dass es auch die Besten und Vorzüglichsten bedeutet."],
    ar: ["بماذا فُسّرت الكلمة المظللة في حديث في صحيح البخاري؟", ["بالعدل", "بقلة العدد", "بالتوسّط في موقع الأرض", "بالتوسّط في المال"], "في حديث أبي سعيد في سؤال قوم نوح هل بلّغهم، فسّر النبي ﷺ الوسط بالعدل، وزاد ابن كثير أنه يعني الخيار الأجود."] },
  { id: "tfl-028", s: "tafsir", g: 2, d: 2, t: ["fasting-verses", "marriage"], src: "Ibn Kathīr, Tafsīr, on 2:187", v: "2:187",
    en: ["What image does the verse shown use for the relation between spouses?", ["Each is a garment for the other", "Each is a field for the other", "Each is a shade for the other", "Each is a pillar for the other"], "The verse permits intimacy on the nights of fasting and describes spouses as garments for one another, conveying closeness, covering and tranquillity."],
    de: ["Welches Bild verwendet der gezeigte Vers für die Beziehung der Ehepartner?", ["Jeder ist ein Gewand für den anderen", "Jeder ist ein Saatfeld für den anderen", "Jeder ist ein Schatten für den anderen", "Jeder ist eine Säule für den anderen"], "Der Vers erlaubt die eheliche Nähe in den Nächten des Fastens und beschreibt die Ehepartner als Gewänder füreinander, was Nähe, Schutz und Ruhe ausdrückt."],
    ar: ["ما الصورة التي تستعملها الآية المعروضة للعلاقة بين الزوجين؟", ["أن كلًّا منهما لباس للآخر", "أن كلًّا منهما حرث للآخر", "أن كلًّا منهما ظلّ للآخر", "أن كلًّا منهما عماد للآخر"], "تبيح الآية الرفث ليلة الصيام وتصف الزوجين بأن كلًّا منهما لباس للآخر، دلالةً على المخالطة والستر والسكن."] },
  { id: "tfl-029", s: "tafsir", g: 2, d: 3, t: ["fasting-verses", "itikaf"], src: "al-Qurṭubī, al-Jāmiʿ li-Aḥkām al-Qurʾān, on 2:187", v: "2:187",
    en: ["Which restriction for those in iʿtikāf is mentioned at the end of the verse shown?", ["No marital relations while in iʿtikāf in the mosques", "No eating between ʿaṣr and maghrib", "No speaking except in remembrance", "No leaving the mosque even for necessities"], "The verse forbids relations with one's spouse while in iʿtikāf in the mosques; the scholars derive from the wording that iʿtikāf takes place in a mosque. Leaving for genuine needs is allowed by consensus."],
    de: ["Welche Einschränkung für die Personen im iʿtikāf nennt das Ende des gezeigten Verses?", ["Keine eheliche Nähe während des iʿtikāf in den Moscheen", "Kein Essen zwischen ʿaṣr und maghrib", "Kein Sprechen außer im Gedenken Allahs", "Kein Verlassen der Moschee, auch nicht für Notwendiges"], "Der Vers verbietet die eheliche Nähe während des iʿtikāf in den Moscheen; die Gelehrten leiten aus dem Wortlaut ab, dass der iʿtikāf in einer Moschee stattfindet. Das Hinausgehen für echte Bedürfnisse ist einhellig erlaubt."],
    ar: ["ما القيد المذكور في آخر الآية المعروضة على المعتكف؟", ["ألّا يباشر زوجته وهو عاكف في المساجد", "ألّا يأكل بين العصر والمغرب", "ألّا يتكلم إلا بذكر", "ألّا يخرج من المسجد ولو لحاجة"], "تنهى الآية عن مباشرة النساء حال الاعتكاف في المساجد، واستدل العلماء بلفظها على أن الاعتكاف يكون في المسجد، والخروج للحاجة جائز بالإجماع."] },
  { id: "tfl-030", s: "tafsir", g: 2, d: 3, t: ["fasting-verses", "dua"], src: "Ibn Kathīr, Tafsīr, on 2:186", v: "2:186",
    en: ["What lesson do commentators draw from the placement of the verse shown among the fasting verses?", ["It encourages supplication during the fast and at its completion", "It shows that supplication replaces a missed fast", "It limits the answering of prayers to Ramaḍān", "It commands a specific prayer before breaking the fast"], "Ibn Kathīr notes that inserting this verse on Allah's nearness and answering the caller between the rulings of fasting is a guidance to strive in supplication during the fast and when completing it."],
    de: ["Welche Lehre ziehen die Kommentatoren aus der Stellung des gezeigten Verses zwischen den Fastenversen?", ["Sie ermuntert zum Bittgebet während des Fastens und bei seinem Abschluss", "Sie zeigt, dass das Bittgebet ein versäumtes Fasten ersetzt", "Sie beschränkt die Erhörung der Gebete auf den Ramaḍān", "Sie gebietet ein bestimmtes Gebet vor dem Fastenbrechen"], "Ibn Kathīr bemerkt, dass dieser Vers über Allahs Nähe und die Erhörung des Rufenden zwischen den Fastenbestimmungen eine Anleitung ist, sich während des Fastens und bei seinem Abschluss um das Bittgebet zu bemühen."],
    ar: ["ما الفائدة التي استنبطها المفسرون من موضع الآية المعروضة بين آيات الصيام؟", ["الحثّ على الدعاء في الصيام وعند إكمال العدة", "أن الدعاء يقوم مقام الصوم الفائت", "حصر إجابة الدعاء في رمضان", "الأمر بدعاء معيّن قبل الفطر"], "ذكر ابن كثير أن إدخال هذه الآية في القرب وإجابة الداعي بين أحكام الصيام إرشاد إلى الاجتهاد في الدعاء عند إكمال العدة بل وعند كل فطر."] },
  { id: "tfl-031", s: "tafsir", g: 2, d: 2, t: ["ayat-al-kursi", "divine-attributes"], src: "Ibn Kathīr, Tafsīr, on 2:255", v: "2:255", w: 10,
    en: ["The verse shown negates of Allah the highlighted word and sleep. What does the highlighted word mean?", ["Drowsiness, the onset of sleep", "Forgetfulness", "Fatigue after effort", "Heedlessness"], "Sina is the slumber that precedes sleep; negating both drowsiness and sleep expresses the perfection of Allah's attribute al-Qayyūm, who sustains everything without lapse."],
    de: ["Der gezeigte Vers verneint für Allah das hervorgehobene Wort und den Schlaf. Was bedeutet das hervorgehobene Wort?", ["Schläfrigkeit, das Einnicken vor dem Schlaf", "Vergesslichkeit", "Ermüdung nach Anstrengung", "Achtlosigkeit"], "Sina ist das Schlummern, das dem Schlaf vorausgeht; die Verneinung von Schläfrigkeit und Schlaf drückt die Vollkommenheit von Allahs Eigenschaft al-Qayyūm aus, der alles ohne Unterbrechung erhält."],
    ar: ["تنفي الآية المعروضة عن الله الكلمةَ المظللة والنوم، فما معنى الكلمة المظللة؟", ["النعاس الذي يسبق النوم", "النسيان", "التعب بعد الجهد", "الغفلة"], "السِّنة هي النعاس الذي يتقدّم النوم، ونفيها مع النوم دليل كمال قيّوميته سبحانه القائم على كل شيء بلا فتور."] },
  { id: "tfl-032", s: "tafsir", g: 2, d: 3, t: ["al-baqara", "freedom-of-belief"], src: "Ibn Kathīr, Tafsīr, on 2:256", v: "2:256", w: 17,
    en: ["How do the early commentators explain 'the firmest handhold' that contains the highlighted word?", ["As faith, Islam or the testimony of tawḥīd", "As the Kaʿba and its sanctity", "As the covenant with the People of the Book", "As obedience to the ruler"], "Ibn Kathīr reports that the salaf explained it as īmān, Islam, or lā ilāha illā Allāh; he notes that these explanations agree in meaning."],
    de: ["Wie erklären die frühen Kommentatoren den „festesten Halt“, zu dem das hervorgehobene Wort gehört?", ["Als Glauben, Islam oder das Bekenntnis des Tawḥīd", "Als die Kaʿba und ihre Unverletzlichkeit", "Als den Bund mit den Schriftbesitzern", "Als Gehorsam gegenüber dem Herrscher"], "Ibn Kathīr berichtet, dass die Altvorderen ihn als īmān, Islam oder lā ilāha illā Allāh erklärten, und bemerkt, dass diese Erklärungen inhaltlich übereinstimmen."],
    ar: ["بماذا فسّر السلف «العروة الوثقى» التي منها الكلمة المظللة؟", ["بالإيمان أو الإسلام أو كلمة التوحيد", "بالكعبة وحرمتها", "بالعهد مع أهل الكتاب", "بطاعة وليّ الأمر"], "نقل ابن كثير عن السلف تفسيرها بالإيمان أو الإسلام أو لا إله إلا الله، وذكر أن هذه الأقوال متفقة في المعنى."] },
  { id: "tfl-033", s: "tafsir", g: 2, d: 2, t: ["debt-verse", "testimony"], src: "Ibn Kathīr, Tafsīr, on 2:282", v: "2:282",
    en: ["What reason does the verse shown give for two women witnesses taking the place of one man?", ["So that if one of them errs, the other can remind her", "So that the transaction is announced more widely", "So that one can write while the other dictates", "So that the debtor may choose between them"], "The verse states the wisdom explicitly: if one of the two forgets or errs, the other reminds her. The context is testimony on financial transactions."],
    de: ["Welchen Grund nennt der gezeigte Vers dafür, dass zwei Zeuginnen an die Stelle eines Mannes treten?", ["Damit, wenn eine von ihnen irrt, die andere sie erinnern kann", "Damit das Geschäft weiter bekannt gemacht wird", "Damit eine schreibt, während die andere diktiert", "Damit der Schuldner zwischen ihnen wählen kann"], "Der Vers nennt den Grund ausdrücklich: Wenn eine der beiden vergisst oder irrt, erinnert die andere sie. Der Zusammenhang ist das Zeugnis bei finanziellen Geschäften."],
    ar: ["ما العلة التي تذكرها الآية المعروضة لجعل امرأتين مكان رجل في الشهادة؟", ["أنه إذا نسيت إحداهما ذكّرتها الأخرى", "أن يشتهر العقد بين الناس أكثر", "أن تكتب إحداهما وتملي الأخرى", "أن يختار المدين بينهما"], "صرّحت الآية بالعلة: إن نسيت إحداهما أو أخطأت نبّهتها الأخرى، والسياق سياق الشهادة على المعاملات المالية."] },
  { id: "tfl-034", s: "tafsir", g: 2, d: 3, t: ["end-of-baqara", "virtues-of-verses"], src: "Ibn Kathīr, Tafsīr, on 2:285 (hadith of Abū Masʿūd in al-Bukhārī and Muslim)", v: "2:285",
    en: ["What virtue of the last two verses of al-Baqara, beginning with the verse shown, is reported in al-Bukhārī and Muslim?", ["Whoever recites them at night, they will suffice him", "Whoever recites them is forgiven the sins of a year", "They were revealed together with Āyat al-Kursī", "They are read in every rakʿa of the witr"], "In the hadith of Abū Masʿūd al-Badrī, the Prophet said that whoever recites the last two verses of al-Baqara at night, they suffice him."],
    de: ["Welcher Vorzug der letzten beiden Verse von al-Baqara, beginnend mit dem gezeigten Vers, ist bei al-Bukhārī und Muslim überliefert?", ["Wer sie nachts rezitiert, dem genügen sie", "Wer sie rezitiert, dem werden die Sünden eines Jahres vergeben", "Sie wurden zusammen mit Āyat al-Kursī offenbart", "Sie werden in jeder Rakʿa des Witr gelesen"], "Im Hadith des Abū Masʿūd al-Badrī sagte der Prophet, dass die letzten beiden Verse von al-Baqara dem genügen, der sie in einer Nacht rezitiert."],
    ar: ["ما فضل خاتمتَي سورة البقرة، أولاهما الآية المعروضة، الوارد في الصحيحين؟", ["أن من قرأهما في ليلة كانتا كافيتين له", "من قرأهما غُفرت له ذنوب سنة", "أنهما نزلتا مع آية الكرسي", "أنهما تُقرآن في كل ركعة من الوتر"], "في حديث أبي مسعود البدري في الصحيحين أخبر النبي ﷺ أن قراءة هاتين الآيتين ليلًا تكفي قارئهما."] },
  { id: "tfl-035", s: "tafsir", g: 2, d: 2, t: ["al-i-imran", "reflection-and-dhikr"], src: "Ibn Kathīr, Tafsīr, on 3:191", v: "3:191",
    en: ["How are 'those of understanding' described in the verse shown?", ["They remember Allah standing, sitting and lying on their sides, and reflect on creation", "They pray all night and fast all day without break", "They withdraw from people to live in the wilderness", "They debate the People of the Book with proofs"], "The verse describes them as remembering Allah in every posture and reflecting on the creation of the heavens and the earth, concluding that it was not created in vain."],
    de: ["Wie werden „die Verständigen“ im gezeigten Vers beschrieben?", ["Sie gedenken Allahs im Stehen, Sitzen und Liegen und denken über die Schöpfung nach", "Sie beten die ganze Nacht und fasten jeden Tag ohne Unterbrechung", "Sie ziehen sich von den Menschen in die Wildnis zurück", "Sie streiten mit den Schriftbesitzern mit Beweisen"], "Der Vers beschreibt sie als Menschen, die Allahs in jeder Haltung gedenken und über die Erschaffung der Himmel und der Erde nachdenken und erkennen, dass sie nicht sinnlos erschaffen wurde."],
    ar: ["كيف وُصف أولو الألباب في الآية المعروضة؟", ["يذكرون الله في القيام والقعود والاضطجاع ويتفكرون في الخلق", "يقومون الليل كله ويصومون الدهر بلا فطر", "يعتزلون الناس ويسكنون البراري", "يجادلون أهل الكتاب بالحجج"], "تصفهم الآية بذكر الله في كل أحوالهم والتفكر في خلق السماوات والأرض، فيخلصون إلى أنه لم يُخلق باطلًا."] },
  { id: "tfl-036", s: "tafsir", g: 2, d: 3, t: ["uhud", "death-of-the-prophet"], src: "Ibn Kathīr, Tafsīr, on 3:144 (report in Ṣaḥīḥ al-Bukhārī)", v: "3:144",
    en: ["On which later occasion did Abū Bakr recite the verse shown, as reported in Ṣaḥīḥ al-Bukhārī?", ["On the day the Prophet died", "At the Treaty of al-Ḥudaybiya", "At the conquest of Mecca", "At the Farewell Pilgrimage"], "Revealed in the context of Uḥud, when it was rumoured that the Prophet had been killed, the verse was recited by Abū Bakr on the day of the Prophet's death; the people felt as if they had never heard it before."],
    de: ["Bei welchem späteren Anlass rezitierte Abū Bakr den gezeigten Vers, wie in Ṣaḥīḥ al-Bukhārī berichtet?", ["Am Todestag des Propheten", "Beim Vertrag von al-Ḥudaybiya", "Bei der Eroberung Mekkas", "Bei der Abschiedspilgerfahrt"], "Der im Zusammenhang mit Uḥud offenbarte Vers, als das Gerücht vom Tod des Propheten aufkam, wurde von Abū Bakr am Todestag des Propheten rezitiert; die Menschen waren, als hätten sie ihn nie zuvor gehört."],
    ar: ["في أيّ مناسبة لاحقة تلا أبو بكر الآية المعروضة كما في صحيح البخاري؟", ["يوم وفاة النبي ﷺ", "في صلح الحديبية", "يوم فتح مكة", "في حجة الوداع"], "نزلت الآية في سياق أحد حين أُشيع أن النبي ﷺ قُتل، وتلاها أبو بكر يوم وفاته ﷺ فكأن الناس لم يسمعوها قبل ذلك."] },
  { id: "tfl-037", s: "tafsir", g: 2, d: 2, t: ["uhud", "martyrs"], src: "Ibn Kathīr, Tafsīr, on 3:169", v: "3:169",
    en: ["What does the verse shown state about those killed in the way of Allah?", ["They are alive with their Lord, receiving provision", "They sleep until the Day of Resurrection", "Their reward depends on the outcome of the battle", "They will be returned to the world once more"], "The verse forbids thinking of the martyrs as dead: they are alive with their Lord and provided for. The commentators cite it in connection with the martyrs of Uḥud."],
    de: ["Was sagt der gezeigte Vers über die auf Allahs Weg Getöteten?", ["Sie sind lebendig bei ihrem Herrn und werden versorgt", "Sie schlafen bis zum Tag der Auferstehung", "Ihr Lohn hängt vom Ausgang der Schlacht ab", "Sie werden noch einmal in die Welt zurückgebracht"], "Der Vers verbietet, die Märtyrer für tot zu halten: Sie sind lebendig bei ihrem Herrn und werden versorgt. Die Kommentatoren führen ihn im Zusammenhang mit den Märtyrern von Uḥud an."],
    ar: ["ماذا تقرّر الآية المعروضة عن الذين قُتلوا في سبيل الله؟", ["أنهم أحياء عند الله ولهم رزق", "أنهم نائمون إلى يوم القيامة", "أن أجرهم متوقف على نتيجة المعركة", "أنهم يُردّون إلى الدنيا مرة أخرى"], "تنهى الآية عن ظنّ الشهداء أمواتًا، فهم أحياء عند الله يجري عليهم رزقه، ويذكرها المفسرون في سياق شهداء أحد."] },
  { id: "tfl-038", s: "tafsir", g: 2, d: 2, t: ["surah-al-nisa", "kinship"], src: "Ibn Kathīr, Tafsīr, on 4:1", v: "4:1",
    en: ["With what reminder does the verse shown open Sūrat al-Nisāʾ?", ["All people were created from a single soul, so fear Allah and honour the ties of kinship", "Women are to be given their dowries willingly", "The property of orphans must not be consumed", "Inheritance is divided according to fixed shares"], "The surah opens by reminding mankind of their common origin from one soul, from which its mate was created, and commands taqwā and respect for the ties of the womb (al-arḥām)."],
    de: ["Mit welcher Ermahnung eröffnet der gezeigte Vers Sūrat al-Nisāʾ?", ["Alle Menschen wurden aus einer einzigen Seele erschaffen; fürchten Sie Allah und achten Sie die Verwandtschaftsbande", "Den Frauen ist die Brautgabe bereitwillig zu geben", "Das Vermögen der Waisen darf nicht verzehrt werden", "Das Erbe wird nach festen Anteilen geteilt"], "Die Sure beginnt mit der Erinnerung an den gemeinsamen Ursprung der Menschen aus einer Seele, aus der ihre Gattin erschaffen wurde, und gebietet Gottesfurcht und die Achtung der Verwandtschaftsbande (al-arḥām)."],
    ar: ["بأيّ تذكير تُفتتح سورة النساء في الآية المعروضة؟", ["أن أصل البشر نفس واحدة، مع الأمر بالتقوى وصلة الرحم", "إيتاء النساء صدقاتهن نحلة", "النهي عن أكل أموال اليتامى", "قسمة الميراث بفروض مقدّرة"], "تفتتح السورة بتذكير الناس بأصلهم المشترك من نفس واحدة خُلق منها زوجها، وتأمر بالتقوى وصلة الأرحام."] },
  { id: "tfl-039", s: "tafsir", g: 2, d: 3, t: ["surah-al-nisa", "inimitability"], src: "Ibn Kathīr, Tafsīr, on 4:82", v: "4:82",
    en: ["What argument for the divine origin of the Quran does the verse shown present?", ["Had it come from other than Allah, much contradiction would be found in it", "No human could produce even one surah like it", "It foretold the victory of the Romans", "It was revealed to an unlettered prophet"], "The verse calls for reflection (tadabbur) and argues that a text from anyone other than Allah would contain much inconsistency; the Quran's coherence points to its source. The challenge to produce a surah is made in other verses."],
    de: ["Welches Argument für den göttlichen Ursprung des Koran bringt der gezeigte Vers?", ["Wäre er von einem anderen als Allah, fände man darin viel Widerspruch", "Kein Mensch könnte auch nur eine Sure wie ihn hervorbringen", "Er sagte den Sieg der Römer voraus", "Er wurde einem schriftunkundigen Propheten offenbart"], "Der Vers ruft zum Nachsinnen (tadabbur) auf und argumentiert, dass ein Text von einem anderen als Allah viel Widersprüchliches enthielte; die Stimmigkeit des Koran verweist auf seine Quelle. Die Herausforderung, eine Sure hervorzubringen, steht in anderen Versen."],
    ar: ["ما الحجة على المصدر الإلهي للقرآن في الآية المعروضة؟", ["أنه لو صدر عن غير الله لكثر فيه التناقض", "أنه لا يستطيع بشر أن يأتي بسورة مثله", "أنه أخبر بغلبة الروم", "أنه نزل على نبي أمّي"], "تدعو الآية إلى التدبّر، وتحتج بأن كلامًا يصدر عن غير الله لا يسلم من تناقض كثير، فاتساق القرآن دليل على مصدره، أما التحدّي بسورة ففي آيات أخرى."] },
  { id: "tfl-040", s: "tafsir", g: 2, d: 3, t: ["al-maida", "farewell-pilgrimage"], src: "Ibn Kathīr, Tafsīr, on 5:3 (report of ʿUmar in Ṣaḥīḥ al-Bukhārī)", v: "5:3",
    en: ["According to ʿUmar's report in Ṣaḥīḥ al-Bukhārī, when was the passage about the perfection of the religion in the verse shown revealed?", ["On the day of ʿArafa, which was a Friday, during the Farewell Pilgrimage", "On the night of the conquest of Mecca", "On the day of al-Ghadīr after the pilgrimage", "In the last week of the Prophet's illness"], "When a Jewish man told ʿUmar that such a verse would have been taken as a festival, ʿUmar replied that he knew the day and place: it was revealed at ʿArafa on a Friday."],
    de: ["Wann wurde nach ʿUmars Bericht in Ṣaḥīḥ al-Bukhārī der Abschnitt über die Vollendung der Religion im gezeigten Vers offenbart?", ["Am Tag von ʿArafa, einem Freitag, während der Abschiedspilgerfahrt", "In der Nacht der Eroberung Mekkas", "Am Tag von al-Ghadīr nach der Pilgerfahrt", "In der letzten Woche der Krankheit des Propheten"], "Als ein jüdischer Mann ʿUmar sagte, man hätte den Tag eines solchen Verses zum Fest gemacht, antwortete ʿUmar, er kenne Tag und Ort: Er wurde in ʿArafa an einem Freitag offenbart."],
    ar: ["متى نزل مقطع إكمال الدين في الآية المعروضة بحسب خبر عمر في صحيح البخاري؟", ["يوم عرفة وكان يوم جمعة في حجة الوداع", "ليلة فتح مكة", "يوم الغدير بعد الحج", "في الأسبوع الأخير من مرض النبي ﷺ"], "لمّا ذكر رجل من اليهود لعمر أنهم كانوا سيتخذون يوم نزول مثل هذه الآية عيدًا، أجابه عمر بأنه يعرف يومها ومكانها: نزلت بعرفة في يوم جمعة."] },
  { id: "tfl-041", s: "tafsir", g: 2, d: 2, t: ["surah-al-anam", "story-of-ibrahim"], src: "Ibn Kathīr, Tafsīr, on 6:76–79", v: "6:76",
    en: ["In the passage beginning with the verse shown, what did Ibrāhīm point out about the star, the moon and the sun?", ["That they set, so none of them is worthy of worship", "That they are angels who intercede with Allah", "That they determine people's destinies", "That they were created before the earth"], "Ibrāhīm argued with his people that a thing which sets and disappears cannot be a lord; he then turned his face to the Creator of the heavens and the earth. Ibn Kathīr understands it as a debate with his people, not personal doubt."],
    de: ["Worauf wies Ibrāhīm in der Passage, die mit dem gezeigten Vers beginnt, bei Stern, Mond und Sonne hin?", ["Dass sie untergehen und daher keiner von ihnen der Anbetung würdig ist", "Dass sie Engel sind, die bei Allah Fürsprache einlegen", "Dass sie das Schicksal der Menschen bestimmen", "Dass sie vor der Erde erschaffen wurden"], "Ibrāhīm führte seinem Volk vor, dass etwas, das untergeht und verschwindet, kein Herr sein kann; dann wandte er sich dem Schöpfer der Himmel und der Erde zu. Ibn Kathīr versteht dies als Streitgespräch mit seinem Volk, nicht als eigenen Zweifel."],
    ar: ["ماذا بيّن إبراهيم في الكوكب والقمر والشمس في المقطع الذي أوله الآية المعروضة؟", ["أنها تغيب فلا يستحق شيء منها العبادة", "أنها ملائكة تشفع عند الله", "أنها تتحكم في أقدار الناس", "أنها خُلقت قبل الأرض"], "حاجّ إبراهيم قومه بأن ما يأفل ويغيب لا يكون ربًّا، ثم أعلن توجّهه بالعبادة إلى خالق السماوات والأرض، وقرّر ابن كثير أنه كان مناظرًا لقومه لا ناظرًا شاكًّا."] },
  { id: "tfl-042", s: "tafsir", g: 2, d: 2, t: ["surah-al-araf", "story-of-musa"], src: "Ibn Kathīr, Tafsīr, on 7:143", v: "7:143",
    en: ["What happened when Mūsā asked to see his Lord, according to the verse shown?", ["Allah manifested Himself to the mountain, it crumbled and Mūsā fell unconscious", "Mūsā was shown the Garden and the Fire", "The sea split and Mūsā crossed it", "Mūsā received the staff and the shining hand"], "Allah told Mūsā to look at the mountain; when his Lord manifested Himself to it, it was levelled and Mūsā fell down unconscious, then repented on waking."],
    de: ["Was geschah nach dem gezeigten Vers, als Mūsā darum bat, seinen Herrn zu sehen?", ["Allah offenbarte Sich dem Berg, dieser zerfiel und Mūsā fiel ohnmächtig nieder", "Mūsā wurden das Paradies und das Feuer gezeigt", "Das Meer spaltete sich und Mūsā durchquerte es", "Mūsā erhielt den Stab und die leuchtende Hand"], "Allah sagte Mūsā, er solle auf den Berg schauen; als sein Herr Sich dem Berg offenbarte, wurde er eingeebnet und Mūsā fiel ohnmächtig nieder und bereute, als er zu sich kam."],
    ar: ["ماذا حدث حين سأل موسى رؤية ربه بحسب الآية المعروضة؟", ["تجلّى الله للجبل فانهدّ وسقط موسى مغشيًّا عليه", "أُري موسى الجنة والنار", "انفلق البحر فعبره موسى", "أُعطي موسى العصا واليد البيضاء"], "أمر الله موسى أن ينظر إلى الجبل، فلما تجلّى له سبحانه انهدّ الجبل وسقط موسى مغشيًّا عليه، فلما أفاق تاب."] },
  { id: "tfl-043", s: "tafsir", g: 2, d: 3, t: ["surah-al-anfal", "spoils"], src: "Ibn Kathīr, Tafsīr, on 8:41", v: "8:41",
    en: ["What portion of the spoils does the verse shown assign to Allah, the Messenger, relatives, orphans, the poor and the wayfarer?", ["One fifth", "One third", "One quarter", "One tenth"], "The verse sets aside one fifth (al-khums) of war spoils for the listed recipients; the remaining four fifths go to the fighters."],
    de: ["Welchen Anteil der Beute weist der gezeigte Vers Allah, dem Gesandten, den Verwandten, Waisen, Armen und Reisenden zu?", ["Ein Fünftel", "Ein Drittel", "Ein Viertel", "Ein Zehntel"], "Der Vers bestimmt ein Fünftel (al-khums) der Kriegsbeute für die genannten Empfänger; die übrigen vier Fünftel gehen an die Kämpfer."],
    ar: ["ما القدر من الغنيمة الذي خصّصته الآية المعروضة للأصناف المذكورة فيها؟", ["الخُمس", "الثُّلث", "الرُّبع", "العُشر"], "خصّت الآية خُمس الغنيمة لهذه الأصناف، والأربعة الأخماس الباقية للغانمين."] },
  { id: "tfl-044", s: "tafsir", g: 2, d: 2, t: ["surah-al-tawba", "zakah"], src: "Ibn Kathīr, Tafsīr, on 9:60", v: "9:60",
    en: ["How many categories of recipients of ṣadaqāt (zakāt) does the verse shown list?", ["Eight", "Six", "Seven", "Five"], "The verse lists eight: the poor, the needy, those employed to collect it, those whose hearts are to be reconciled, freeing slaves, debtors, in the way of Allah, and the wayfarer."],
    de: ["Wie viele Empfängergruppen der ṣadaqāt (Zakāt) nennt der gezeigte Vers?", ["Acht", "Sechs", "Sieben", "Fünf"], "Der Vers nennt acht: die Armen, die Bedürftigen, die mit der Einsammlung Beauftragten, jene, deren Herzen gewonnen werden sollen, den Freikauf von Sklaven, die Verschuldeten, den Weg Allahs und den Reisenden."],
    ar: ["كم صنفًا من مستحقي الصدقات (الزكاة) تذكر الآية المعروضة؟", ["ثمانية", "ستة", "سبعة", "خمسة"], "تذكر الآية ثمانية أصناف: الفقير، والمسكين، والعامل على جمعها، والمؤلَّف قلبه، وتحرير الرقيق، والمدين، والمجاهد في سبيل الله، والمسافر المنقطع."] },
  { id: "tfl-045", s: "tafsir", g: 2, d: 3, t: ["surah-yunus", "story-of-musa"], src: "Ibn Kathīr, Tafsīr, on 10:90–92", v: "10:92",
    en: ["What does the verse shown say would happen to Pharaoh after his late declaration of faith at drowning?", ["His body would be preserved as a sign for those after him", "He would be forgiven because he believed before death", "He would be raised again to rule Egypt", "His people would follow his last words"], "Pharaoh's faith at the moment of drowning was not accepted; the verse states that his body would be cast out and preserved so that those after him would take a lesson."],
    de: ["Was sagt der gezeigte Vers darüber, was nach Pharaos spätem Glaubensbekenntnis beim Ertrinken mit ihm geschehen würde?", ["Sein Leib würde als Zeichen für die Nachkommenden bewahrt", "Ihm würde vergeben, weil er vor dem Tod glaubte", "Er würde wieder als Herrscher Ägyptens erweckt", "Sein Volk würde seinen letzten Worten folgen"], "Pharaos Glaube im Augenblick des Ertrinkens wurde nicht angenommen; der Vers sagt, dass sein Leib geborgen und bewahrt würde, damit die Späteren eine Lehre daraus ziehen."],
    ar: ["ماذا تذكر الآية المعروضة عن مصير فرعون بعد إيمانه المتأخر عند الغرق؟", ["أن جسده يُحفظ ليكون عبرة لمن بعده", "أنه يُغفر له لأنه آمن قبل الموت", "أنه يُبعث ليحكم مصر من جديد", "أن قومه يتّبعون كلماته الأخيرة"], "لم يُقبل إيمان فرعون حين أدركه الغرق، وتذكر الآية أن الله يُخرج جسده ويحفظه ليعتبر به من يأتي بعده."] },
  { id: "tfl-046", s: "tafsir", g: 2, d: 2, t: ["surah-hud", "story-of-nuh"], src: "Ibn Kathīr, Tafsīr, on 11:44", v: "11:44",
    en: ["Where did Nūḥ's ark come to rest, according to the verse shown?", ["On al-Jūdī", "On Mount Sinai", "On Mount Uḥud", "On Mount ʿArafāt"], "When the earth swallowed its water and the sky ceased, the matter was concluded and the ark settled on al-Jūdī; Ibn Kathīr describes it as a mountain in the Jazīra region."],
    de: ["Wo kam die Arche Nūḥs nach dem gezeigten Vers zur Ruhe?", ["Auf al-Jūdī", "Auf dem Berg Sinai", "Auf dem Berg Uḥud", "Auf dem Berg ʿArafāt"], "Als die Erde ihr Wasser verschluckte und der Himmel aufhörte, war die Sache entschieden, und die Arche ließ sich auf al-Jūdī nieder; Ibn Kathīr beschreibt ihn als Berg in der Region al-Jazīra."],
    ar: ["أين استقرت سفينة نوح بحسب الآية المعروضة؟", ["على الجودي", "على طور سيناء", "على جبل أحد", "على جبل عرفات"], "لمّا غاض الماء في الأرض وكفّت السماء عن المطر انتهى الأمر ورست السفينة على الجودي، وذكر ابن كثير أنه جبل بالجزيرة."] },
  { id: "tfl-047", s: "tafsir", g: 2, d: 2, t: ["surah-yusuf", "story-of-yusuf"], src: "Ibn Kathīr, Tafsīr, on 12:31", v: "12:31",
    en: ["What happened to the women of the city when Yūsuf came out before them, according to the verse shown?", ["They cut their hands, amazed, and said he was a noble angel, not a human", "They mocked the governor's wife and left the banquet", "They testified that Yūsuf was innocent", "They asked the king to release him"], "The governor's wife gave each woman a knife; on seeing Yūsuf they were so struck that they cut their hands and declared he could not be a mere human."],
    de: ["Was geschah nach dem gezeigten Vers mit den Frauen der Stadt, als Yūsuf vor sie trat?", ["Sie schnitten sich vor Staunen in die Hände und sagten, er sei ein edler Engel, kein Mensch", "Sie verspotteten die Frau des Statthalters und verließen das Mahl", "Sie bezeugten Yūsufs Unschuld", "Sie baten den König, ihn freizulassen"], "Die Frau des Statthalters gab jeder Frau ein Messer; beim Anblick Yūsufs waren sie so überwältigt, dass sie sich in die Hände schnitten und erklärten, er könne kein gewöhnlicher Mensch sein."],
    ar: ["ماذا حدث لنسوة المدينة حين خرج عليهن يوسف بحسب الآية المعروضة؟", ["جرحن أيديهن دهشةً ونفين أن يكون بشرًا عاديًّا", "سخرن من امرأة العزيز وتركن المجلس", "شهدن ببراءة يوسف", "طلبن من الملك إطلاقه"], "أعطت امرأة العزيز كل واحدة منهن سكينًا، فلما رأين يوسف بُهتن بجماله فجرحن أيديهن ونفين أن يكون من البشر العاديين."] },
  { id: "tfl-048", s: "tafsir", g: 2, d: 2, t: ["surah-al-nahl", "dawah"], src: "Ibn Kathīr, Tafsīr, on 16:125", v: "16:125",
    en: ["Which means of calling to the way of Allah are named in the verse shown?", ["Wisdom, good admonition and arguing in the best manner", "Signs, miracles and warnings of punishment", "Gifts, alliances and treaties", "Poetry, sermons and public debates only"], "The verse lays down the method of daʿwa: ḥikma, al-mawʿiẓa al-ḥasana, and disputing in the way that is best."],
    de: ["Welche Mittel der Einladung zum Weg Allahs nennt der gezeigte Vers?", ["Weisheit, schöne Ermahnung und das Streiten auf die beste Art", "Zeichen, Wunder und Androhung der Strafe", "Geschenke, Bündnisse und Verträge", "Nur Dichtung, Predigten und öffentliche Debatten"], "Der Vers legt die Methode der daʿwa fest: ḥikma, al-mawʿiẓa al-ḥasana und das Streitgespräch auf die beste Weise."],
    ar: ["ما وسائل الدعوة إلى سبيل الله المذكورة في الآية المعروضة؟", ["الحكمة والوعظ الحسن والمجادلة بأحسن طريقة", "الآيات والمعجزات والإنذار بالعذاب", "الهدايا والأحلاف والمعاهدات", "الشعر والخطب والمناظرات العامة فقط"], "ترسم الآية منهج الدعوة: الحكمة، والوعظ الحسن، والمناظرة بأحسن الأساليب."] },
  { id: "tfl-049", s: "tafsir", g: 2, d: 3, t: ["al-isra-commandments", "spending"], src: "Ibn Kathīr, Tafsīr, on 17:29", v: "17:29",
    en: ["What attitude to spending does the image of the hand in the verse shown teach?", ["Moderation: neither miserliness nor squandering everything", "Giving away all wealth before death", "Keeping wealth until one's children are grown", "Spending only on obligatory duties"], "The verse forbids both tying one's hand to one's neck (stinginess) and stretching it out completely (extravagance), warning of blame and destitution; Ibn Kathīr explains it as a command to moderation."],
    de: ["Welche Haltung zum Ausgeben lehrt das Bild der Hand im gezeigten Vers?", ["Maßhalten: weder Geiz noch völliges Verschwenden", "Das gesamte Vermögen vor dem Tod zu verschenken", "Das Vermögen zu behalten, bis die Kinder erwachsen sind", "Nur für Pflichtabgaben auszugeben"], "Der Vers verbietet sowohl, die Hand an den Hals zu fesseln (Geiz), als auch, sie ganz auszustrecken (Verschwendung), und warnt vor Tadel und Not; Ibn Kathīr erklärt es als Gebot des Maßhaltens."],
    ar: ["ما الموقف من الإنفاق الذي تعلّمه صورة اليد في الآية المعروضة؟", ["الاعتدال بلا بخل ولا تبذير", "التصدق بكل المال قبل الموت", "إمساك المال حتى يكبر الأولاد", "الاقتصار على النفقات الواجبة"], "تنهى الآية بصورة اليد المقيّدة عن البخل، وبصورة اليد المفتوحة تمامًا عن الإسراف، وفسّرها ابن كثير بالأمر بالاقتصاد."] },
  { id: "tfl-050", s: "tafsir", g: 2, d: 3, t: ["al-isra-commandments", "knowledge"], src: "Ibn Kathīr, Tafsīr, on 17:36", v: "17:36",
    en: ["What does the verse shown forbid, and why?", ["Following what one has no knowledge of, since hearing, sight and heart will be questioned", "Walking proudly on the earth, since one cannot split it", "Approaching the property of the orphan, since it is a trust", "Killing children for fear of poverty, since Allah provides"], "The verse forbids pursuing or speaking about what one does not know, for the hearing, the sight and the heart will each be asked about. The other options belong to neighbouring verses."],
    de: ["Was verbietet der gezeigte Vers, und warum?", ["Dem zu folgen, wovon man kein Wissen hat, da Gehör, Augenlicht und Herz befragt werden", "Hochmütig auf der Erde zu gehen, da man sie nicht spalten kann", "Sich dem Vermögen der Waise zu nähern, da es anvertraut ist", "Kinder aus Angst vor Armut zu töten, da Allah versorgt"], "Der Vers verbietet, dem nachzugehen oder über das zu reden, wovon man kein Wissen hat, denn Gehör, Augenlicht und Herz werden jeweils befragt. Die anderen Optionen gehören zu benachbarten Versen."],
    ar: ["عمّ تنهى الآية المعروضة، ولماذا؟", ["عن اتّباع ما لا علم للإنسان به لأن السمع والبصر والقلب ستُسأل", "عن المشي بتكبّر لأن الإنسان لا يشق الأرض", "عن الاقتراب من مال اليتيم لأنه أمانة", "عن قتل الأولاد خوف الفقر لأن الله يرزق"], "تنهى الآية عن القول والاتّباع بغير علم، لأن السمع والبصر والقلب كلٌّ منها يُسأل عنه، والخيارات الأخرى في آيات مجاورة."] },
  { id: "tfl-051", s: "tafsir", g: 3, d: 4, t: ["types-of-people", "al-baqara", "salaf-views"], src: "al-Ṭabarī, Jāmiʿ al-Bayān, on 2:8; Ibn Kathīr, Tafsīr, on 2:8", v: "2:8",
    en: ["The verse shown begins the description of the hypocrites. How does Mujāhid divide the opening verses of al-Baqara among the three types of people?", ["Four verses for the believers, two for the disbelievers, thirteen for the hypocrites", "Five verses for the believers, two for the disbelievers, twelve for the hypocrites", "Four verses for the believers, three for the disbelievers, twelve for the hypocrites", "Three verses for the believers, two for the disbelievers, fourteen for the hypocrites"], "Al-Ṭabarī reports from Mujāhid that 2:2–5 describe the believers, 2:6–7 the open disbelievers and 2:8–20 the hypocrites. The long treatment of the hypocrites reflects how dangerous and hidden their state is."],
    de: ["Der gezeigte Vers beginnt die Beschreibung der Heuchler. Wie teilt Mujāhid die Anfangsverse von al-Baqara auf die drei Menschengruppen auf?", ["Vier Verse für die Gläubigen, zwei für die Ungläubigen, dreizehn für die Heuchler", "Fünf Verse für die Gläubigen, zwei für die Ungläubigen, zwölf für die Heuchler", "Vier Verse für die Gläubigen, drei für die Ungläubigen, zwölf für die Heuchler", "Drei Verse für die Gläubigen, zwei für die Ungläubigen, vierzehn für die Heuchler"], "Al-Ṭabarī überliefert von Mujāhid, dass 2:2–5 die Gläubigen, 2:6–7 die offenen Ungläubigen und 2:8–20 die Heuchler beschreiben. Die ausführliche Behandlung der Heuchler zeigt, wie gefährlich und verborgen ihr Zustand ist."],
    ar: ["تبدأ الآية المعروضة وصف المنافقين، فكيف قسّم مجاهد الآيات الأولى من البقرة على أصناف الناس الثلاثة؟", ["أربع آيات في المؤمنين، وآيتان في الكافرين، وثلاث عشرة في المنافقين", "خمس آيات في المؤمنين، وآيتان في الكافرين، واثنتا عشرة في المنافقين", "أربع آيات في المؤمنين، وثلاث في الكافرين، واثنتا عشرة في المنافقين", "ثلاث آيات في المؤمنين، وآيتان في الكافرين، وأربع عشرة في المنافقين"], "روى الطبري عن مجاهد أن الآيات ٢–٥ في المؤمنين، و٦–٧ في الكافرين المجاهرين، و٨–٢٠ في المنافقين، وإطالة الحديث عن المنافقين لخطر حالهم وخفائه."] },
  { id: "tfl-052", s: "tafsir", g: 3, d: 3, t: ["story-of-adam", "repentance"], src: "Ibn Kathīr, Tafsīr, on 2:37", v: "2:37",
    en: ["According to the view reported from Ibn ʿAbbās, Mujāhid and others, what were the 'words' Ādam received from his Lord in the verse shown?", ["The supplication of repentance mentioned in 7:23", "The names he had been taught in 2:31", "The testimony of faith he would teach his children", "A promise that he would return to the Garden"], "Many of the salaf explained the words as the prayer of Ādam and Ḥawwāʾ in 7:23, admitting that they had wronged themselves and asking for forgiveness and mercy; with these words Allah accepted his repentance."],
    de: ["Was waren nach der Ansicht, die von Ibn ʿAbbās, Mujāhid und anderen überliefert ist, die „Worte“, die Ādam im gezeigten Vers von seinem Herrn empfing?", ["Das Reuegebet, das in 7:23 erwähnt ist", "Die Namen, die ihn 2:31 zufolge gelehrt wurden", "Das Glaubensbekenntnis, das er seine Kinder lehren sollte", "Ein Versprechen, ins Paradies zurückzukehren"], "Viele der Altvorderen erklärten die Worte als das Gebet von Ādam und Ḥawwāʾ in 7:23, in dem sie bekennen, sich selbst Unrecht getan zu haben, und um Vergebung und Barmherzigkeit bitten; mit diesen Worten nahm Allah seine Reue an."],
    ar: ["ما الكلمات التي تلقّاها آدم من ربه في الآية المعروضة بحسب القول المروي عن ابن عباس ومجاهد وغيرهما؟", ["دعاء التوبة المذكور في ٧:٢٣", "الأسماء التي عُلّمها في ٢:٣١", "كلمة التوحيد التي يعلّمها أولاده", "وعد بالعودة إلى الجنة"], "فسّر كثير من السلف الكلمات بدعاء آدم وحواء في ٧:٢٣ الذي اعترفا فيه بظلم أنفسهما وسألا المغفرة والرحمة، فتاب الله عليه بها."] },
  { id: "tfl-053", s: "tafsir", g: 3, d: 3, t: ["story-of-adam", "angels"], src: "Ibn Kathīr, Tafsīr, on 2:30", v: "2:30",
    en: ["How does Ibn Kathīr characterise the angels' question about placing on earth one who would cause corruption, in the verse shown?", ["As an inquiry about the wisdom, not an objection or envy", "As a protest that Allah rebuked as disobedience", "As an expression of envy towards Ādam", "As a claim that they knew the unseen"], "Ibn Kathīr states that the angels' words were not an objection to Allah nor envy of the children of Ādam, but a request to understand the wisdom; Allah answered that He knows what they do not."],
    de: ["Wie charakterisiert Ibn Kathīr die Frage der Engel im gezeigten Vers, ob Allah jemanden einsetze, der Unheil stiftet?", ["Als Frage nach der Weisheit, nicht als Einwand oder Neid", "Als Protest, den Allah als Ungehorsam tadelte", "Als Ausdruck des Neides gegenüber Ādam", "Als Anspruch, das Verborgene zu kennen"], "Ibn Kathīr sagt, die Worte der Engel seien weder ein Einwand gegen Allah noch Neid auf die Kinder Ādams gewesen, sondern die Bitte, die Weisheit zu verstehen; Allah antwortete, Er wisse, was sie nicht wissen."],
    ar: ["كيف وصف ابن كثير سؤال الملائكة في الآية المعروضة عن جعل من يُفسد في الأرض؟", ["بأنه استعلام عن الحكمة لا اعتراض ولا حسد", "بأنه احتجاج عاتبهم الله عليه بوصفه معصية", "بأنه حسد لآدم", "بأنه ادعاء لعلم الغيب"], "قرّر ابن كثير أن قول الملائكة لم يكن اعتراضًا على الله ولا حسدًا لبني آدم، وإنما سؤال استعلام واستكشاف عن الحكمة، فأجابهم الله بأنه يعلم ما لا يعلمون."] },
  { id: "tfl-054", s: "tafsir", g: 3, d: 4, t: ["qibla", "hadith-in-tafsir"], src: "Ibn Kathīr, Tafsīr, on 2:143 (hadith of al-Barāʾ in Ṣaḥīḥ al-Bukhārī)", v: "2:143", w: 40,
    en: ["What is meant by the highlighted word, according to the occasion reported in Ṣaḥīḥ al-Bukhārī?", ["The prayers offered towards Bayt al-Maqdis before the change of qibla", "The faith of the People of the Book before Islam", "The belief of those who emigrated to Abyssinia", "The faith of the Companions killed at Badr"], "Al-Barāʾ reports that some Muslims had died before the qibla was changed and people wondered about them; the verse assured that Allah would not let their 'faith', meaning their prayer towards Jerusalem, go to waste. Prayer is called īmān because it expresses faith."],
    de: ["Was ist mit dem hervorgehobenen Wort nach dem in Ṣaḥīḥ al-Bukhārī überlieferten Anlass gemeint?", ["Die Gebete in Richtung Bayt al-Maqdis vor der Änderung der Gebetsrichtung", "Der Glaube der Schriftbesitzer vor dem Islam", "Der Glaube derer, die nach Abessinien auswanderten", "Der Glaube der bei Badr gefallenen Gefährten"], "Al-Barāʾ berichtet, dass einige Muslime vor der Änderung der Gebetsrichtung gestorben waren und man sich um sie sorgte; der Vers versicherte, dass Allah ihren „Glauben“, also ihr Gebet Richtung Jerusalem, nicht verloren gehen lässt. Das Gebet heißt īmān, weil es Ausdruck des Glaubens ist."],
    ar: ["ما المراد بالكلمة المظللة بحسب سبب النزول المروي في صحيح البخاري؟", ["صلاتهم إلى بيت المقدس قبل تحويل القبلة", "إيمان أهل الكتاب قبل الإسلام", "إيمان من هاجروا إلى الحبشة", "إيمان الصحابة الذين قُتلوا في بدر"], "روى البراء أن أناسًا ماتوا قبل تحويل القبلة فتساءل الناس عنهم، فطمأنهم الله أن إيمانهم، أي صلاتهم إلى بيت المقدس، محفوظ الأجر عنده، وسُمّيت الصلاة إيمانًا لأنها من أعظم مظاهره."] },
  { id: "tfl-055", s: "tafsir", g: 3, d: 3, t: ["qibla", "hadith-in-tafsir"], src: "Ibn Kathīr, Tafsīr, on 2:144 (hadith of al-Barāʾ in Ṣaḥīḥ al-Bukhārī)", v: "2:144",
    en: ["According to al-Barāʾ ibn ʿĀzib in Ṣaḥīḥ al-Bukhārī, for how long did the Prophet pray towards Bayt al-Maqdis in Medina before the command in the verse shown?", ["Sixteen or seventeen months", "Three years", "Ten months", "Twenty-four months"], "Al-Barāʾ reports that the Prophet prayed towards Bayt al-Maqdis for sixteen or seventeen months after the hijra while wishing to face the Kaʿba, and then the change was revealed."],
    de: ["Wie lange betete der Prophet nach al-Barāʾ ibn ʿĀzib in Ṣaḥīḥ al-Bukhārī in Medina Richtung Bayt al-Maqdis, bevor der Befehl im gezeigten Vers kam?", ["Sechzehn oder siebzehn Monate", "Drei Jahre", "Zehn Monate", "Vierundzwanzig Monate"], "Al-Barāʾ berichtet, dass der Prophet nach der Hidschra sechzehn oder siebzehn Monate Richtung Bayt al-Maqdis betete und sich wünschte, zur Kaʿba gewandt zu beten; dann wurde die Änderung offenbart."],
    ar: ["كم صلّى النبي ﷺ في المدينة إلى بيت المقدس قبل الأمر في الآية المعروضة، بحسب البراء بن عازب في صحيح البخاري؟", ["ستة عشر أو سبعة عشر شهرًا", "ثلاث سنين", "عشرة أشهر", "أربعة وعشرين شهرًا"], "روى البراء أن النبي ﷺ صلّى بعد الهجرة إلى بيت المقدس ستة عشر أو سبعة عشر شهرًا وكان يحب أن يتوجّه إلى الكعبة، ثم نزل التحويل."] },
  { id: "tfl-056", s: "tafsir", g: 3, d: 3, t: ["fasting-verses", "hadith-in-tafsir"], src: "Ibn Kathīr, Tafsīr, on 2:187 (hadith of ʿAdī ibn Ḥātim in Ṣaḥīḥ al-Bukhārī)", v: "2:187",
    en: ["ʿAdī ibn Ḥātim at first understood the 'white thread and black thread' in the verse shown literally. How did the Prophet explain them?", ["As the whiteness of the day and the darkness of the night", "As the first and second calls to prayer", "As two threads that become distinguishable at sunrise", "As the light of the moon and the darkness before it"], "ʿAdī put a white and a black cord under his pillow and kept looking at them; the Prophet explained that the meaning is the whiteness of day emerging from the darkness of night, i.e. true dawn."],
    de: ["ʿAdī ibn Ḥātim verstand den „weißen und schwarzen Faden“ im gezeigten Vers zunächst wörtlich. Wie erklärte der Prophet sie?", ["Als das Weiß des Tages und das Dunkel der Nacht", "Als den ersten und den zweiten Gebetsruf", "Als zwei Fäden, die bei Sonnenaufgang unterscheidbar werden", "Als das Mondlicht und die Dunkelheit davor"], "ʿAdī legte eine weiße und eine schwarze Schnur unter sein Kissen und schaute immer wieder darauf; der Prophet erklärte, gemeint sei das Weiß des Tages, das aus dem Dunkel der Nacht hervortritt, also die wahre Morgendämmerung."],
    ar: ["فهم عديّ بن حاتم الخيط الأبيض والخيط الأسود في الآية المعروضة على ظاهره أول الأمر، فبماذا فسّرهما النبي ﷺ؟", ["ببياض النهار وسواد الليل", "بالأذان الأول والأذان الثاني", "بخيطين يتمايزان عند طلوع الشمس", "بضوء القمر والظلمة التي قبله"], "وضع عديّ عقالين أبيض وأسود تحت وسادته وجعل ينظر إليهما، فبيّن النبي ﷺ أن المراد بياض النهار من سواد الليل أي الفجر الصادق."] },
  { id: "tfl-057", s: "tafsir", g: 3, d: 4, t: ["freedom-of-belief", "occasions-of-revelation"], src: "Ibn Kathīr, Tafsīr, on 2:256 (report of Ibn ʿAbbās in Sunan Abī Dāwūd)", v: "2:256",
    en: ["Which occasion of revelation for the verse shown does Ibn Kathīr report from Ibn ʿAbbās?", ["Children of the Anṣār raised among the Jews, whom their parents wanted to compel when Banū al-Naḍīr were expelled", "A Companion who wished to force his Christian servant to pray", "The captives of Badr who were offered Islam in exchange for freedom", "A delegation from Najrān that asked for protection of its churches"], "Ibn ʿAbbās reports that some Anṣārī women whose children did not survive vowed to raise a child as a Jew; when Banū al-Naḍīr were expelled, such children were among them and the Anṣār said they would not leave their sons, and the verse was revealed."],
    de: ["Welchen Offenbarungsanlass des gezeigten Verses überliefert Ibn Kathīr von Ibn ʿAbbās?", ["Bei den Juden aufgewachsene Kinder der Anṣār, die ihre Eltern bei der Vertreibung der Banū al-Naḍīr zwingen wollten", "Ein Gefährte, der seinen christlichen Diener zum Gebet zwingen wollte", "Die Gefangenen von Badr, denen der Islam gegen die Freiheit angeboten wurde", "Eine Abordnung aus Najrān, die um Schutz ihrer Kirchen bat"], "Ibn ʿAbbās berichtet, dass manche Frauen der Anṣār, deren Kinder nicht am Leben blieben, gelobten, ein Kind als Juden aufzuziehen; als die Banū al-Naḍīr vertrieben wurden, waren solche Kinder unter ihnen, und die Anṣār wollten ihre Söhne nicht zurücklassen. Da wurde der Vers offenbart."],
    ar: ["ما سبب نزول الآية المعروضة الذي أورده ابن كثير عن ابن عباس؟", ["أبناء للأنصار نشؤوا في اليهود أراد آباؤهم إكراههم عند إجلاء بني النضير", "صحابي أراد إكراه خادمه النصراني على الصلاة", "أسرى بدر الذين عُرض عليهم الإسلام مقابل الحرية", "وفد نجران الذي طلب حماية كنائسه"], "روى ابن عباس أن المرأة من الأنصار كانت لا يعيش لها ولد فتنذر إن عاش أن تهوّده، فلما أُجليت بنو النضير كان فيهم من أبناء الأنصار فأبى الأنصار أن يتركوا أبناءهم، فنزلت الآية."] },
  { id: "tfl-058", s: "tafsir", g: 3, d: 3, t: ["muhkam-mutashabih", "al-i-imran", "hadith-in-tafsir"], src: "Ibn Kathīr, Tafsīr, on 3:7 (hadith of ʿĀʾisha in al-Bukhārī and Muslim)", v: "3:7",
    en: ["In the hadith of ʿĀʾisha on the verse shown, what did the Prophet say about those who follow the mutashābih verses?", ["They are the ones Allah has named, so beware of them", "They should be answered with the muḥkam verses only in private", "They are excused if they intend to learn", "They are the well-grounded in knowledge"], "After reciting the verse, the Prophet said that when you see those who pursue what is ambiguous in it, they are the ones Allah named, so be wary of them. The verse describes them as seeking discord and their own interpretation."],
    de: ["Was sagte der Prophet im Hadith der ʿĀʾisha zum gezeigten Vers über jene, die den mutashābih-Versen folgen?", ["Sie sind diejenigen, die Allah genannt hat, also hüten Sie sich vor ihnen", "Man soll ihnen nur unter vier Augen mit den muḥkam-Versen antworten", "Sie sind entschuldigt, wenn sie lernen wollen", "Sie sind die im Wissen Gefestigten"], "Nach der Rezitation des Verses sagte der Prophet: Wenn man jene sieht, die dem Mehrdeutigen darin nachgehen, so sind sie es, die Allah genannt hat, und man soll sich vor ihnen hüten. Der Vers beschreibt sie als solche, die Zwietracht und eigene Deutung suchen."],
    ar: ["ماذا قال النبي ﷺ في حديث عائشة عند الآية المعروضة عن الذين يتّبعون المتشابه؟", ["أنهم الذين عناهم الله فينبغي الحذر منهم", "يُردّ عليهم بالمحكم سرًّا فقط", "هم معذورون إن قصدوا التعلّم", "هم الراسخون في العلم"], "بيّن النبي ﷺ بعد تلاوة الآية أن من يتتبّعون المتشابه هم الذين عناهم الله وأمر بالحذر منهم، والآية تصفهم بطلب الفتنة وطلب تأويله على أهوائهم."] },
  { id: "tfl-059", s: "tafsir", g: 3, d: 4, t: ["uhud", "occasions-of-revelation"], src: "Ibn Kathīr, Tafsīr, on 3:122 (report of Jābir in Ṣaḥīḥ al-Bukhārī)", v: "3:122",
    en: ["According to Jābir ibn ʿAbd Allāh in Ṣaḥīḥ al-Bukhārī, which two groups 'almost lost heart' at Uḥud, as the verse shown mentions?", ["Banū Salima and Banū Ḥāritha", "Banū Qurayẓa and Banū al-Naḍīr", "Aws and Khazraj as a whole", "Banū Ghifār and Banū Aslam"], "Jābir said the verse was revealed about his own people, Banū Salima, and Banū Ḥāritha, and that they were glad of it because the verse also says Allah was their protector. Banū Qurayẓa and al-Naḍīr were Jewish tribes."],
    de: ["Welche beiden Gruppen „verloren beinahe den Mut“ bei Uḥud, wie der gezeigte Vers erwähnt, nach Jābir ibn ʿAbd Allāh in Ṣaḥīḥ al-Bukhārī?", ["Banū Salima und Banū Ḥāritha", "Banū Qurayẓa und Banū al-Naḍīr", "Aws und Khazraj insgesamt", "Banū Ghifār und Banū Aslam"], "Jābir sagte, der Vers sei über seinen eigenen Stamm Banū Salima und über Banū Ḥāritha offenbart worden, und sie freuten sich darüber, weil der Vers auch sagt, dass Allah ihr Beschützer war. Banū Qurayẓa und al-Naḍīr waren jüdische Stämme."],
    ar: ["بحسب جابر بن عبد الله في صحيح البخاري، ما الطائفتان اللتان همّتا بالفشل يوم أحد كما في الآية المعروضة؟", ["بنو سلمة وبنو حارثة", "بنو قريظة وبنو النضير", "الأوس والخزرج جميعًا", "بنو غفار وبنو أسلم"], "قال جابر إن الآية نزلت في قومه بني سلمة وفي بني حارثة، وإنهم سُرّوا بها لأن فيها أن الله وليّهما، أما قريظة والنضير فقبيلتان من اليهود."] },
  { id: "tfl-060", s: "tafsir", g: 3, d: 3, t: ["surah-al-anam", "hadith-in-tafsir", "shirk"], src: "Ibn Kathīr, Tafsīr, on 6:82 (hadith of Ibn Masʿūd in Ṣaḥīḥ al-Bukhārī)", v: "6:82",
    en: ["When the Companions were troubled by the word 'ẓulm' in the verse shown, how did the Prophet explain it?", ["As shirk, citing Luqmān's words in 31:13", "As any minor sin committed knowingly", "As injustice towards other people only", "As neglect of the obligatory prayers"], "The Companions asked who among them had not wronged himself; the Prophet said it is not what they thought but shirk, referring to Luqmān's statement that shirk is a tremendous wrong."],
    de: ["Als die Gefährten über das Wort „ẓulm“ im gezeigten Vers beunruhigt waren, wie erklärte es der Prophet?", ["Als Schirk, unter Verweis auf Luqmāns Worte in 31:13", "Als jede bewusst begangene kleine Sünde", "Nur als Unrecht gegenüber anderen Menschen", "Als Vernachlässigung der Pflichtgebete"], "Die Gefährten fragten, wer von ihnen sich nicht selbst Unrecht getan habe; der Prophet sagte, es sei nicht das, was sie dachten, sondern Schirk, und verwies auf Luqmāns Aussage, Schirk sei ein gewaltiges Unrecht."],
    ar: ["لمّا شقّ على الصحابة لفظ الظلم في الآية المعروضة، بماذا فسّره النبي ﷺ؟", ["بالشرك، مستشهدًا بقول لقمان في ٣١:١٣", "بكل صغيرة تُرتكب عن علم", "بظلم الناس فقط", "بترك الصلوات المفروضة"], "قال الصحابة: أيّنا لم يظلم نفسه؟ فقال النبي ﷺ ليس كما تظنون، إنما هو الشرك، وأحال على وصية لقمان لابنه التي وصفت الشرك بأنه أعظم الظلم."] },
  { id: "tfl-061", s: "tafsir", g: 3, d: 4, t: ["surah-al-anam", "commandments"], src: "Ibn Kathīr, Tafsīr, on 6:151 (statement of Ibn Masʿūd in Jāmiʿ al-Tirmidhī)", v: "6:151",
    en: ["What did Ibn Masʿūd say about the verse shown and the two verses after it?", ["Whoever wishes to see the Prophet's testament bearing his seal should read them", "They were the last verses revealed before the Prophet's death", "They abrogate the commandments given to Banū Isrāʾīl", "They were recited by the Prophet at every Friday sermon"], "Ibn Kathīr cites Ibn Masʿūd's statement, reported by al-Tirmidhī, that 6:151–153 are like the sealed testament of the Prophet; they gather prohibitions such as shirk, disobeying parents, killing children and approaching indecency."],
    de: ["Was sagte Ibn Masʿūd über den gezeigten Vers und die beiden folgenden Verse?", ["Wer das versiegelte Testament des Propheten sehen will, soll sie lesen", "Sie waren die letzten Verse vor dem Tod des Propheten", "Sie heben die Gebote der Banū Isrāʾīl auf", "Der Prophet rezitierte sie in jeder Freitagspredigt"], "Ibn Kathīr führt die von al-Tirmidhī überlieferte Aussage Ibn Masʿūds an, dass 6:151–153 wie das versiegelte Vermächtnis des Propheten sind; sie fassen Verbote wie Schirk, Ungehorsam gegenüber den Eltern, Kindstötung und Schamlosigkeit zusammen."],
    ar: ["ماذا قال ابن مسعود عن الآية المعروضة والآيتين بعدها؟", ["أنهن بمنزلة وصية النبي ﷺ المختومة بخاتمه", "أنهن آخر ما نزل قبل وفاة النبي ﷺ", "أنهن نسخن وصايا بني إسرائيل", "أن النبي ﷺ كان يقرؤهن في كل خطبة جمعة"], "أورد ابن كثير قول ابن مسعود عند الترمذي في أن الآيات ٦:١٥١–١٥٣ كالوصية المختومة للنبي ﷺ، وفيها النهي عن الشرك وعقوق الوالدين وقتل الأولاد وقرب الفواحش."] },
  { id: "tfl-062", s: "tafsir", g: 3, d: 3, t: ["surah-al-araf", "afterlife"], src: "Ibn Kathīr, Tafsīr, on 7:46", v: "7:46",
    en: ["Who are the 'people of al-Aʿrāf' in the verse shown, according to the view Ibn Kathīr reports from Ḥudhayfa, Ibn ʿAbbās and Ibn Masʿūd?", ["People whose good and bad deeds are equal", "The prophets who will intercede for their nations", "Martyrs who disobeyed their parents", "Angels who guard the gates of the Garden"], "Several views exist, but the best known, reported from these Companions, is that they are people whose good and bad deeds balance; they wait on the heights between the Garden and the Fire before finally entering the Garden."],
    de: ["Wer sind die „Leute von al-Aʿrāf“ im gezeigten Vers nach der Ansicht, die Ibn Kathīr von Ḥudhayfa, Ibn ʿAbbās und Ibn Masʿūd überliefert?", ["Menschen, deren gute und schlechte Taten gleich wiegen", "Die Propheten, die für ihre Völker Fürsprache einlegen", "Märtyrer, die ihren Eltern ungehorsam waren", "Engel, die die Tore des Paradieses bewachen"], "Es gibt mehrere Ansichten, doch die bekannteste, von diesen Gefährten überliefert, ist, dass ihre guten und schlechten Taten sich die Waage halten; sie warten auf den Höhen zwischen Paradies und Feuer, bevor sie schließlich ins Paradies eingehen."],
    ar: ["من أصحاب الأعراف في الآية المعروضة بحسب القول الذي أورده ابن كثير عن حذيفة وابن عباس وابن مسعود؟", ["قوم استوت حسناتهم وسيئاتهم", "الأنبياء الذين يشفعون لأممهم", "شهداء عصوا آباءهم", "ملائكة يحرسون أبواب الجنة"], "في المسألة أقوال، وأشهرها المروي عن هؤلاء الصحابة أنهم قوم تساوت حسناتهم وسيئاتهم، يُوقفون على الأعراف بين الجنة والنار ثم يدخلون الجنة."] },
  { id: "tfl-063", s: "tafsir", g: 3, d: 3, t: ["surah-al-tawba", "repentance"], src: "Ibn Kathīr, Tafsīr, on 9:118 (hadith of Kaʿb ibn Mālik in al-Bukhārī and Muslim)", v: "9:118",
    en: ["Who are 'the three who were left behind' whose repentance is accepted in the verse shown?", ["Kaʿb ibn Mālik, Murāra ibn al-Rabīʿ and Hilāl ibn Umayya", "Abū Lubāba, Kaʿb ibn Mālik and Ḥāṭib ibn Abī Baltaʿa", "Three hypocrites who built the mosque of ḍirār", "Three Bedouins who refused to pay zakāt"], "They stayed behind from Tabūk without excuse, were boycotted for fifty nights until the earth felt narrow for them, and were then forgiven, as Kaʿb narrates in his long hadith."],
    de: ["Wer sind „die drei Zurückgelassenen“, deren Reue im gezeigten Vers angenommen wird?", ["Kaʿb ibn Mālik, Murāra ibn al-Rabīʿ und Hilāl ibn Umayya", "Abū Lubāba, Kaʿb ibn Mālik und Ḥāṭib ibn Abī Baltaʿa", "Drei Heuchler, die die Moschee al-ḍirār bauten", "Drei Beduinen, die die Zakāt verweigerten"], "Sie blieben ohne Entschuldigung dem Feldzug von Tabūk fern, wurden fünfzig Nächte lang gemieden, bis ihnen die Erde eng wurde, und dann wurde ihnen vergeben, wie Kaʿb in seinem langen Hadith erzählt."],
    ar: ["من الثلاثة الذين خُلّفوا وتاب الله عليهم في الآية المعروضة؟", ["كعب بن مالك ومرارة بن الربيع وهلال بن أمية", "أبو لبابة وكعب بن مالك وحاطب بن أبي بلتعة", "ثلاثة منافقين بنوا مسجد الضرار", "ثلاثة أعراب منعوا الزكاة"], "تخلّفوا عن غزوة تبوك بلا عذر فهُجروا خمسين ليلة حتى اشتدّ عليهم الكرب، ثم تاب الله عليهم كما في حديث كعب الطويل."] },
  { id: "tfl-064", s: "tafsir", g: 3, d: 3, t: ["surah-yunus", "story-of-yunus"], src: "Ibn Kathīr, Tafsīr, on 10:98", v: "10:98",
    en: ["What exception does the verse shown highlight about the people of Yūnus?", ["Their faith benefited them when they believed as punishment approached", "They were the only people saved by a flood", "They were the only nation never sent a warner", "Their city was raised to the sky and overturned"], "No town that believed upon seeing the punishment was benefited by it except the people of Yūnus: when they believed, Allah removed the humiliating punishment and let them enjoy life for a time."],
    de: ["Welche Ausnahme hebt der gezeigte Vers beim Volk des Yūnus hervor?", ["Ihr Glaube nützte ihnen, als sie beim Herannahen der Strafe glaubten", "Sie waren das einzige durch eine Flut gerettete Volk", "Sie waren das einzige Volk ohne Warner", "Ihre Stadt wurde in den Himmel gehoben und umgestürzt"], "Keine Stadt, die beim Anblick der Strafe glaubte, zog Nutzen daraus außer dem Volk des Yūnus: Als sie glaubten, nahm Allah die erniedrigende Strafe von ihnen und ließ sie eine Zeit lang das Leben genießen."],
    ar: ["ما الاستثناء الذي تبرزه الآية المعروضة في قوم يونس؟", ["أن إيمانهم نفعهم حين آمنوا عند اقتراب العذاب", "أنهم القوم الوحيدون الذين نجوا من طوفان", "أنهم الأمة الوحيدة التي لم يأتها نذير", "أن قريتهم رُفعت إلى السماء ثم قُلبت"], "لم تنتفع قرية بإيمانها عند معاينة العذاب إلا قوم يونس، فلما آمنوا كشف الله عنهم العذاب المهين وأبقاهم يتمتعون بالحياة مدة من الزمن."] },
  { id: "tfl-065", s: "tafsir", g: 3, d: 4, t: ["surah-hud", "steadfastness"], src: "al-Qurṭubī, al-Jāmiʿ li-Aḥkām al-Qurʾān, on 11:112", v: "11:112",
    en: ["What is Ibn ʿAbbās reported to have said about the verse shown, which commands steadfastness as one was commanded?", ["No verse was revealed to the Prophet that was harder on him than this one", "It was the first verse revealed in Medina", "It abrogated the command of patience in Mecca", "It was revealed in reply to a question of the Jews"], "Al-Qurṭubī reports from Ibn ʿAbbās that no verse was harder on the Prophet than this command to istiqāma, and connects it with the report that Sūrat Hūd and its sisters turned his hair grey."],
    de: ["Was soll Ibn ʿAbbās über den gezeigten Vers gesagt haben, der Standhaftigkeit gebietet, wie es befohlen wurde?", ["Kein Vers, der dem Propheten offenbart wurde, war schwerer für ihn als dieser", "Er war der erste in Medina offenbarte Vers", "Er hob das Gebot der Geduld in Mekka auf", "Er wurde als Antwort auf eine Frage der Juden offenbart"], "Al-Qurṭubī überliefert von Ibn ʿAbbās, dass kein Vers schwerer für den Propheten war als dieses Gebot der istiqāma, und verbindet dies mit dem Bericht, dass Sūrat Hūd und ihre Schwestern sein Haar ergrauen ließen."],
    ar: ["ماذا رُوي عن ابن عباس في الآية المعروضة التي تأمر بالاستقامة كما أُمر؟", ["ما نزلت على النبي ﷺ آية أشدّ عليه منها", "أنها أول آية نزلت بالمدينة", "أنها نسخت الأمر بالصبر في مكة", "أنها نزلت جوابًا لسؤال اليهود"], "نقل القرطبي عن ابن عباس أنه لم تنزل على النبي ﷺ آية أشدّ ولا أشقّ عليه من هذه الآية، وربط ذلك بما رُوي من أن سورة هود وأخواتها شيّبته."] },
  { id: "tfl-066", s: "tafsir", g: 3, d: 4, t: ["surah-hud", "occasions-of-revelation", "repentance"], src: "Ibn Kathīr, Tafsīr, on 11:114 (hadith of Ibn Masʿūd in Ṣaḥīḥ al-Bukhārī)", v: "11:114",
    en: ["What occasion is reported in Ṣaḥīḥ al-Bukhārī for the verse shown, which states that good deeds remove bad deeds?", ["A man who had kissed a woman came to the Prophet regretting it", "A Companion who missed the ʿaṣr prayer at the trench", "A Bedouin who urinated in the mosque", "A man who broke his fast by intercourse in Ramaḍān"], "Ibn Masʿūd reports that a man kissed a woman and came to the Prophet; the verse on establishing prayer at both ends of the day was revealed, and when he asked if it was for him alone, the Prophet said it was for all of his community."],
    de: ["Welcher Anlass wird in Ṣaḥīḥ al-Bukhārī für den gezeigten Vers berichtet, der sagt, dass gute Taten die schlechten tilgen?", ["Ein Mann, der eine Frau geküsst hatte, kam reuevoll zum Propheten", "Ein Gefährte, der am Graben das ʿaṣr-Gebet versäumte", "Ein Beduine, der in der Moschee urinierte", "Ein Mann, der im Ramaḍān durch Beischlaf das Fasten brach"], "Ibn Masʿūd berichtet, dass ein Mann eine Frau küsste und zum Propheten kam; da wurde der Vers über das Gebet an beiden Enden des Tages offenbart, und auf seine Frage, ob dies nur für ihn gelte, sagte der Prophet, es gelte für seine ganze Gemeinschaft."],
    ar: ["ما سبب نزول الآية المعروضة، التي تقرّر أن الأعمال الصالحة تمحو السيئات، كما في صحيح البخاري؟", ["رجل أصاب من امرأة قبلة فأتى النبي ﷺ نادمًا", "صحابي فاتته صلاة العصر يوم الخندق", "أعرابي بال في المسجد", "رجل أفطر بالجماع في رمضان"], "روى ابن مسعود أن رجلًا أصاب من امرأة قبلة فأتى النبي ﷺ فنزلت الآية في أداء الصلاة في أول النهار وآخره، فسأل الرجل هل هذا خاص به، فأخبره النبي ﷺ أنه لأمته كلها."] },
  { id: "tfl-067", s: "tafsir", g: 3, d: 3, t: ["surah-ibrahim", "afterlife", "hadith-in-tafsir"], src: "Ibn Kathīr, Tafsīr, on 14:27 (hadith of al-Barāʾ in Ṣaḥīḥ al-Bukhārī)", v: "14:27",
    en: ["According to the hadith of al-Barāʾ in Ṣaḥīḥ al-Bukhārī, to what does the 'firm word' in the hereafter in the verse shown refer?", ["The believer's answer when questioned in the grave", "The testimony of the limbs on the Day of Judgement", "The intercession of the Prophet", "The weighing of deeds on the Scale"], "The Prophet explained that when the Muslim is questioned in the grave he testifies that there is no god but Allah and that Muḥammad is His Messenger; this is the firmness Allah grants."],
    de: ["Worauf bezieht sich nach dem Hadith des al-Barāʾ in Ṣaḥīḥ al-Bukhārī das „feste Wort“ im Jenseits im gezeigten Vers?", ["Auf die Antwort des Gläubigen bei der Befragung im Grab", "Auf das Zeugnis der Glieder am Tag des Gerichts", "Auf die Fürsprache des Propheten", "Auf das Wiegen der Taten auf der Waage"], "Der Prophet erklärte, dass der Muslim bei der Befragung im Grab bezeugt, dass es keinen Gott gibt außer Allah und dass Muḥammad Sein Gesandter ist; das ist die Festigkeit, die Allah schenkt."],
    ar: ["إلامَ يشير القول الثابت في الآخرة في الآية المعروضة بحسب حديث البراء في صحيح البخاري؟", ["جواب المؤمن عند السؤال في القبر", "شهادة الجوارح يوم القيامة", "شفاعة النبي ﷺ", "وزن الأعمال في الميزان"], "بيّن النبي ﷺ أن المسلم إذا سُئل في القبر شهد أن لا إله إلا الله وأن محمدًا رسول الله، فذلك التثبيت الذي يمنّ الله به."] },
  { id: "tfl-068", s: "tafsir", g: 3, d: 3, t: ["surah-al-hijr", "al-fatiha", "hadith-in-tafsir"], src: "Ibn Kathīr, Tafsīr, on 15:87 (hadith of Abū Saʿīd ibn al-Muʿallā in Ṣaḥīḥ al-Bukhārī)", v: "15:87",
    en: ["In the hadith of Abū Saʿīd ibn al-Muʿallā in Ṣaḥīḥ al-Bukhārī, what are the 'seven oft-repeated' mentioned in the verse shown?", ["Sūrat al-Fātiḥa", "The seven long surahs from al-Baqara onwards", "The seven verses of Āyat al-Kursī and its neighbours", "The seven surahs beginning with ḥā-mīm"], "The Prophet told Abū Saʿīd that al-Fātiḥa is the seven oft-repeated and the great Quran he was given. Some salaf named the seven long surahs, but the hadith settles the matter for most commentators."],
    de: ["Was sind im Hadith des Abū Saʿīd ibn al-Muʿallā in Ṣaḥīḥ al-Bukhārī die „sieben Wiederholten“, die der gezeigte Vers erwähnt?", ["Sūrat al-Fātiḥa", "Die sieben langen Suren ab al-Baqara", "Die sieben Verse von Āyat al-Kursī und ihrer Nachbarn", "Die sieben mit ḥā-mīm beginnenden Suren"], "Der Prophet sagte Abū Saʿīd, dass al-Fātiḥa die sieben Wiederholten und der gewaltige Koran sei, der ihm gegeben wurde. Einige Altvordere nannten die sieben langen Suren, doch der Hadith entscheidet die Frage für die meisten Kommentatoren."],
    ar: ["ما السبع المثاني المذكورة في الآية المعروضة بحسب حديث أبي سعيد بن المعلّى في صحيح البخاري؟", ["سورة الفاتحة", "السبع الطوال من البقرة فما بعدها", "آية الكرسي والآيات المجاورة لها", "السور السبع المفتتحة بحم"], "أخبر النبي ﷺ أبا سعيد أن الفاتحة هي السبع المثاني والقرآن العظيم الذي أوتيه، وقال بعض السلف إنها السبع الطوال، لكن الحديث حسم المسألة عند أكثر المفسرين."] },
  { id: "tfl-069", s: "tafsir", g: 3, d: 4, t: ["surah-al-nahl", "ethics", "salaf-views"], src: "Ibn Kathīr, Tafsīr, on 16:90", v: "16:90",
    en: ["Which description of the verse shown is reported from ʿAbd Allāh ibn Masʿūd?", ["It is the most comprehensive verse in the Quran for good and evil", "It is the verse that most frightened the Companions", "It is the last verse revealed about family law", "It is the verse that abrogated the law of retaliation"], "Ibn Kathīr cites Ibn Masʿūd's statement that this verse gathers all good to be done and all evil to be avoided. Its use at the end of the Friday sermon is a later practice, not part of the verse's explanation."],
    de: ["Welche Beschreibung des gezeigten Verses wird von ʿAbd Allāh ibn Masʿūd überliefert?", ["Er ist der umfassendste Vers des Koran für Gutes und Böses", "Er ist der Vers, der die Gefährten am meisten erschreckte", "Er ist der letzte Vers zum Familienrecht", "Er ist der Vers, der die Wiedervergeltung aufhob"], "Ibn Kathīr führt die Aussage Ibn Masʿūds an, dass dieser Vers alles zu tuende Gute und alles zu meidende Böse zusammenfasst. Seine Rezitation am Ende der Freitagspredigt ist eine spätere Praxis und kein Teil der Erklärung des Verses."],
    ar: ["ما الوصف المروي عن عبد الله بن مسعود للآية المعروضة؟", ["أنها أجمع آية في القرآن للخير والشر", "أنها أشدّ آية أخافت الصحابة", "أنها آخر ما نزل في أحكام الأسرة", "أنها نسخت حكم القصاص"], "أورد ابن كثير عن ابن مسعود أن هذه الآية أجمع ما في القرآن من أمر بالخير ونهي عن الشر، أما قراءتها في آخر خطبة الجمعة فعمل متأخر لا من تفسيرها."] },
  { id: "tfl-070", s: "tafsir", g: 3, d: 3, t: ["surah-al-nahl", "occasions-of-revelation", "coercion"], src: "Ibn Kathīr, Tafsīr, on 16:106", v: "16:106",
    en: ["About which Companion do most commentators say the exception for one compelled while his heart is at peace with faith, in the verse shown, was revealed?", ["ʿAmmār ibn Yāsir", "Bilāl ibn Rabāḥ", "Khabbāb ibn al-Aratt", "Ṣuhayb al-Rūmī"], "Ibn Kathīr notes that most commentators link the verse to ʿAmmār, who was tortured by the polytheists until he said what they demanded; the Prophet told him that if they returned, he might return to it. All four Companions were persecuted, but the verse is tied to ʿAmmār."],
    de: ["Über welchen Gefährten wurde nach den meisten Kommentatoren die Ausnahme für den Gezwungenen, dessen Herz im Glauben ruhig ist, im gezeigten Vers offenbart?", ["ʿAmmār ibn Yāsir", "Bilāl ibn Rabāḥ", "Khabbāb ibn al-Aratt", "Ṣuhayb al-Rūmī"], "Ibn Kathīr bemerkt, dass die meisten Kommentatoren den Vers mit ʿAmmār verbinden, der von den Götzendienern gefoltert wurde, bis er sagte, was sie verlangten; der Prophet sagte ihm, wenn sie es wieder täten, dürfe er es wieder tun. Alle vier wurden verfolgt, doch der Vers ist mit ʿAmmār verbunden."],
    ar: ["في أيّ صحابي نزل استثناء من أُكره على الكفر بلسانه وقلبه ثابت على الإيمان في الآية المعروضة عند أكثر المفسرين؟", ["عمار بن ياسر", "بلال بن رباح", "خبّاب بن الأرتّ", "صهيب الرومي"], "ذكر ابن كثير أن أكثر المفسرين على أنها نزلت في عمار حين عذّبه المشركون حتى قال ما أرادوا، فأذن له النبي ﷺ في مثل ذلك إن أكرهوه مرة أخرى. وكلهم عُذّبوا، لكن الآية مرتبطة بعمار."] },
  { id: "tfl-071", s: "tafsir", g: 3, d: 4, t: ["al-isra", "surah-names"], src: "Ṣaḥīḥ al-Bukhārī, Kitāb al-Tafsīr, Sūrat Banī Isrāʾīl; Ibn Kathīr, Tafsīr, introduction to Sūrat al-Isrāʾ",
    en: ["By which other name does Ibn Masʿūd refer to Sūrat al-Isrāʾ in Ṣaḥīḥ al-Bukhārī, listing it among the earliest surahs he learned?", ["Sūrat Banī Isrāʾīl", "Sūrat al-Miʿrāj", "Sūrat al-Aqṣā", "Sūrat al-Waṣāyā"], "Ibn Masʿūd said that Banī Isrāʾīl, al-Kahf, Maryam, Ṭāhā and al-Anbiyāʾ are among the earliest and most cherished surahs he acquired. Al-Bukhārī titles the chapter of tafsīr with the same name."],
    de: ["Mit welchem anderen Namen bezeichnet Ibn Masʿūd in Ṣaḥīḥ al-Bukhārī Sūrat al-Isrāʾ, als er sie zu den frühesten von ihm erlernten Suren zählt?", ["Sūrat Banī Isrāʾīl", "Sūrat al-Miʿrāj", "Sūrat al-Aqṣā", "Sūrat al-Waṣāyā"], "Ibn Masʿūd sagte, Banī Isrāʾīl, al-Kahf, Maryam, Ṭāhā und al-Anbiyāʾ gehörten zu den frühesten und kostbarsten Suren, die er erworben habe. Al-Bukhārī benennt das Tafsīr-Kapitel ebenso."],
    ar: ["بأيّ اسم آخر سمّى ابن مسعود سورة الإسراء في صحيح البخاري حين عدّها من أوائل ما تعلّم؟", ["سورة بني إسرائيل", "سورة المعراج", "سورة الأقصى", "سورة الوصايا"], "عدّ ابن مسعود بني إسرائيل والكهف ومريم وطه والأنبياء من أقدم السور التي حفظها وأحبّها إليه، وبهذا الاسم ترجم البخاري كتاب التفسير لهذه السورة."] },
  { id: "tfl-072", s: "tafsir", g: 3, d: 3, t: ["al-i-imran", "reflection-and-dhikr", "hadith-in-tafsir"], src: "Ibn Kathīr, Tafsīr, on 3:190 (hadith of Ibn ʿAbbās in Ṣaḥīḥ al-Bukhārī)", v: "3:190",
    en: ["According to Ibn ʿAbbās in Ṣaḥīḥ al-Bukhārī, when did the Prophet recite the passage beginning with the verse shown?", ["When he woke at night, before praying the night prayer", "After every obligatory prayer", "On the night of the Isrāʾ", "When he saw an eclipse"], "Ibn ʿAbbās, who spent a night in the house of his aunt Maymūna, saw the Prophet wake, look at the sky and recite the last ten verses of Āl ʿImrān, then perform wuḍūʾ and pray."],
    de: ["Wann rezitierte der Prophet nach Ibn ʿAbbās in Ṣaḥīḥ al-Bukhārī die Passage, die mit dem gezeigten Vers beginnt?", ["Als er nachts aufwachte, vor dem Nachtgebet", "Nach jedem Pflichtgebet", "In der Nacht der Isrāʾ", "Als er eine Finsternis sah"], "Ibn ʿAbbās, der eine Nacht im Haus seiner Tante Maymūna verbrachte, sah, wie der Prophet aufwachte, zum Himmel blickte und die letzten zehn Verse von Āl ʿImrān rezitierte, dann die Waschung vollzog und betete."],
    ar: ["متى كان النبي ﷺ يتلو المقطع الذي أوله الآية المعروضة بحسب ابن عباس في صحيح البخاري؟", ["حين يستيقظ من الليل قبل صلاة الليل", "دبر كل صلاة مكتوبة", "ليلة الإسراء", "حين رأى الكسوف"], "بات ابن عباس عند خالته ميمونة فرأى النبي ﷺ استيقظ ونظر إلى السماء وقرأ الآيات العشر الأخيرة من آل عمران ثم توضأ وصلّى."] },
  { id: "tfl-073", s: "tafsir", g: 4, d: 5, t: ["story-of-adam", "tafsir-methodology"], src: "Ibn Kathīr, Tafsīr, on 2:30; al-Qurṭubī, al-Jāmiʿ li-Aḥkām al-Qurʾān, on 2:30", v: "2:30", w: 9,
    en: ["Which interpretation of the highlighted word does Ibn Kathīr favour?", ["A people who succeed one another, generation after generation", "Ādam alone, as Allah's deputy exercising His authority", "Only the prophets and the just rulers among Ādam's offspring", "The angels sent down to replace the jinn on earth"], "Ibn Kathīr explains khalīfa as people who succeed each other age after age and says it does not refer to Ādam alone, as some commentators held. Al-Qurṭubī, by contrast, used the verse as a basis for the obligation of appointing an imām."],
    de: ["Welche Deutung des hervorgehobenen Wortes bevorzugt Ibn Kathīr?", ["Menschen, die einander Generation um Generation nachfolgen", "Ādam allein als Statthalter Allahs, der Seine Macht ausübt", "Nur die Propheten und gerechten Herrscher unter Ādams Nachkommen", "Die Engel, die herabgesandt wurden, um die Dschinn zu ersetzen"], "Ibn Kathīr erklärt khalīfa als Menschen, die einander Zeitalter um Zeitalter nachfolgen, und sagt, es sei nicht Ādam allein gemeint, wie manche Kommentatoren meinten. Al-Qurṭubī dagegen nahm den Vers als Grundlage für die Pflicht, einen Imām einzusetzen."],
    ar: ["أيّ تفسير للكلمة المظللة رجّحه ابن كثير؟", ["قوم يخلف بعضهم بعضًا جيلًا بعد جيل", "آدم وحده نائبًا عن الله في تنفيذ أمره", "الأنبياء والحكام العادلون من ذرية آدم فقط", "ملائكة أُنزلوا ليخلفوا الجن في الأرض"], "فسّر ابن كثير الخليفة بقوم يخلف بعضهم بعضًا قرنًا بعد قرن، وذكر أن المراد ليس آدم وحده كما قال بعض المفسرين، أما القرطبي فاستدل بالآية على وجوب نصب الإمام."] },
  { id: "tfl-074", s: "tafsir", g: 4, d: 4, t: ["iblis", "story-of-adam", "salaf-views"], src: "Ibn Kathīr, Tafsīr, on 2:34; al-Ṭabarī, Jāmiʿ al-Bayān, on 2:34", v: "2:34",
    en: ["Which statement correctly describes the views on whether Iblīs, mentioned in the verse shown, was one of the angels?", ["Al-Ḥasan al-Baṣrī held he was never an angel; reports from Ibn ʿAbbās place him in a group of angels called al-jinn", "All the salaf agreed he was the chief of the angels until his refusal", "All the salaf agreed he was a jinn raised by the angels from childhood", "The dispute concerns only whether he later prostrated in secret"], "The exception in the verse led some to count him among the angels, and reports from Ibn ʿAbbās speak of a tribe of angels called al-jinn. Al-Ḥasan al-Baṣrī insisted he was never an angel even for a moment, relying on 18:50, which states he was of the jinn."],
    de: ["Welche Aussage beschreibt die Ansichten darüber, ob der im gezeigten Vers erwähnte Iblīs ein Engel war, zutreffend?", ["Al-Ḥasan al-Baṣrī meinte, er sei nie ein Engel gewesen; Berichte von Ibn ʿAbbās ordnen ihn einer Engelgruppe namens al-jinn zu", "Alle Altvorderen waren sich einig, dass er bis zu seiner Weigerung Oberster der Engel war", "Alle Altvorderen waren sich einig, dass er ein von Engeln aufgezogener Dschinn war", "Der Streit betrifft nur, ob er sich später heimlich niederwarf"], "Die Ausnahme im Vers führte manche dazu, ihn zu den Engeln zu zählen, und Berichte von Ibn ʿAbbās sprechen von einem Engelstamm namens al-jinn. Al-Ḥasan al-Baṣrī bestand darauf, dass er nicht einen Augenblick ein Engel war, gestützt auf 18:50, wonach er zu den Dschinn gehörte."],
    ar: ["أيّ عبارة تصف الأقوال بدقة في كون إبليس المذكور في الآية المعروضة من الملائكة؟", ["قال الحسن البصري لم يكن من الملائكة قط، ورُوي عن ابن عباس أنه من حيّ من الملائكة يُقال لهم الجن", "اتفق السلف على أنه كان رئيس الملائكة حتى امتنع", "اتفق السلف على أنه جنّي ربّته الملائكة منذ صغره", "الخلاف إنما هو في أنه سجد بعد ذلك سرًّا"], "حمل الاستثناء في الآية بعضهم على عدّه من الملائكة، ورُوي عن ابن عباس أنه من قبيل من الملائكة يُسمّون الجن، وأكّد الحسن البصري أنه لم يكن من الملائكة طرفة عين مستدلًّا بـ١٨:٥٠ التي تنص على أنه من الجن."] },
  { id: "tfl-075", s: "tafsir", g: 4, d: 5, t: ["story-of-adam", "tafsir-methodology"], src: "al-Ṭabarī, Jāmiʿ al-Bayān, on 2:35", v: "2:35",
    en: ["After listing the reports identifying the forbidden tree in the verse shown, what conclusion does al-Ṭabarī reach?", ["It was a specific tree whose identity we cannot know, and knowing it brings no benefit", "It was wheat, as the strongest report from Ibn ʿAbbās states", "It was the grapevine, which is why wine was later forbidden", "It was the fig tree, whose leaves they then used to cover themselves"], "Al-Ṭabarī reports views naming wheat, the vine and the fig, then concludes that Allah forbade one particular tree without revealing which; knowing it would not benefit and not knowing it does no harm. This reflects his method of not specifying what revelation leaves unspecified."],
    de: ["Zu welchem Schluss kommt al-Ṭabarī, nachdem er die Berichte zur Bestimmung des verbotenen Baumes im gezeigten Vers aufgeführt hat?", ["Es war ein bestimmter Baum, dessen Art wir nicht wissen können, und dieses Wissen nützt nichts", "Es war Weizen, wie der stärkste Bericht von Ibn ʿAbbās sagt", "Es war der Weinstock, weshalb der Wein später verboten wurde", "Es war der Feigenbaum, mit dessen Blättern sie sich dann bedeckten"], "Al-Ṭabarī führt Ansichten an, die Weizen, Weinstock und Feige nennen, und schließt, dass Allah einen bestimmten Baum verbot, ohne ihn zu benennen; dieses Wissen nützt nicht, und Unkenntnis schadet nicht. Darin zeigt sich seine Methode, nicht festzulegen, was die Offenbarung offenlässt."],
    ar: ["بعد أن ساق الطبري الروايات في تعيين الشجرة المنهيّ عنها في الآية المعروضة، ما الذي انتهى إليه؟", ["أنها شجرة بعينها لا سبيل إلى معرفتها، ولا ينفع العلم بها", "أنها الحنطة كما في أقوى الروايات عن ابن عباس", "أنها الكرمة ولذلك حُرّمت الخمر بعدُ", "أنها التينة التي استترا بورقها بعد ذلك"], "ذكر الطبري أقوالًا في أنها الحنطة أو الكرمة أو التين، ثم قرّر أن الله نهاهما عن شجرة بعينها ولم يبيّنها، وأن العلم بها لا ينفع والجهل بها لا يضر، وهذا من منهجه في عدم تعيين ما أبهمه الوحي."] },
  { id: "tfl-076", s: "tafsir", g: 4, d: 4, t: ["qibla", "salaf-views"], src: "Ibn Kathīr, Tafsīr, on 2:142", v: "2:142", w: 2,
    en: ["Who are meant by the highlighted word, according to Ibn Kathīr's summary of the views?", ["Views name the Arab polytheists, the Jewish scholars or the hypocrites, and the verse covers all of them", "Only the Christians of Najrān, as all reports agree", "Only the hypocrites, by consensus of the Companions", "Only the leaders of Quraysh, the other views being rejected"], "Ibn Kathīr reports that some said the polytheists (al-Zajjāj), others the Jewish rabbis (Mujāhid), others the hypocrites, and concludes that the verse is general to all of them, since each group objected to the change of qibla."],
    de: ["Wer ist mit dem hervorgehobenen Wort nach Ibn Kathīrs Zusammenfassung der Ansichten gemeint?", ["Genannt werden die arabischen Götzendiener, die jüdischen Gelehrten oder die Heuchler, und der Vers umfasst sie alle", "Nur die Christen von Najrān, worin alle Berichte übereinstimmen", "Nur die Heuchler, nach Konsens der Gefährten", "Nur die Anführer der Quraysh, die anderen Ansichten sind verworfen"], "Ibn Kathīr berichtet, dass manche die Götzendiener (al-Zajjāj), andere die jüdischen Gelehrten (Mujāhid), wieder andere die Heuchler nannten, und schließt, dass der Vers alle umfasst, da jede Gruppe die Änderung der Gebetsrichtung kritisierte."],
    ar: ["من المراد بالكلمة المظللة بحسب تلخيص ابن كثير للأقوال؟", ["قيل مشركو العرب، وقيل أحبار اليهود، وقيل المنافقون، والآية عامة فيهم جميعًا", "نصارى نجران وحدهم باتفاق الروايات", "المنافقون وحدهم بإجماع الصحابة", "زعماء قريش وحدهم وما سواه مردود"], "نقل ابن كثير أنه قيل المشركون وهو قول الزجاج، وقيل أحبار اليهود وهو قول مجاهد، وقيل المنافقون، ثم قرّر أن الآية عامة في هؤلاء كلهم لأن كل فريق منهم طعن في تحويل القبلة."] },
  { id: "tfl-077", s: "tafsir", g: 4, d: 5, t: ["fasting-verses", "abrogation"], src: "Ṣaḥīḥ al-Bukhārī, Kitāb al-Tafsīr, on 2:184; Ibn Kathīr, Tafsīr, on 2:184", tr: ["comparative"], v: "2:184",
    en: ["Which statement correctly describes the reports on the fidya clause for 'those who can fast only with hardship' in the verse shown?", ["Salama ibn al-Akwaʿ reported an early choice between fasting and fidya that 2:185 abrogated, while Ibn ʿAbbās held the clause remains for the very old who cannot fast", "All Companions agreed the clause was never abrogated and lets anyone who wishes pay fidya", "All Companions agreed it was abrogated entirely, leaving no concession for the elderly", "The dispute concerns only whether the fidya is one meal or two"], "Both reports are in Ṣaḥīḥ al-Bukhārī: Salama says those who wished could break the fast and pay fidya until the next verse abrogated this, while Ibn ʿAbbās says the clause is not abrogated but applies to the elderly man and woman unable to fast. Ibn Kathīr reconciles them: the general option was abrogated, the concession for the incapable remains."],
    de: ["Welche Aussage beschreibt die Berichte zur Fidya-Klausel für jene, „die nur mit Mühe fasten können“, im gezeigten Vers zutreffend?", ["Salama ibn al-Akwaʿ berichtete eine frühe Wahl zwischen Fasten und Fidya, die 2:185 aufhob, während Ibn ʿAbbās die Klausel für Hochbetagte, die nicht fasten können, fortbestehen sah", "Alle Gefährten waren sich einig, dass die Klausel nie aufgehoben wurde und jedem die Fidya erlaubt", "Alle Gefährten waren sich einig, dass sie ganz aufgehoben wurde, ohne Erleichterung für Betagte", "Der Streit betrifft nur, ob die Fidya eine oder zwei Mahlzeiten beträgt"], "Beide Berichte stehen in Ṣaḥīḥ al-Bukhārī: Salama sagt, wer wollte, konnte das Fasten brechen und Fidya zahlen, bis der nächste Vers dies aufhob; Ibn ʿAbbās sagt, die Klausel sei nicht aufgehoben, sondern gelte für den alten Mann und die alte Frau, die nicht fasten können. Ibn Kathīr vereinbart beides: Die allgemeine Wahl wurde aufgehoben, die Erleichterung für die Unfähigen bleibt."],
    ar: ["أيّ عبارة تصف الروايات في حكم الفدية للذين يطيقون الصيام بمشقة في الآية المعروضة وصفًا صحيحًا؟", ["روى سلمة بن الأكوع تخييرًا أول الأمر بين الصوم والفدية نسخته الآية ٢:١٨٥، وقال ابن عباس إنها باقية في الشيخ الكبير العاجز عن الصوم", "اتفق الصحابة على أنها محكمة تبيح الفدية لكل من شاء", "اتفق الصحابة على نسخها كليًّا فلا رخصة للشيخ الكبير", "الخلاف إنما هو في كون الفدية وجبة أو وجبتين"], "الروايتان في صحيح البخاري: أخبر سلمة أن المسلمين كانوا مخيّرين بين الصوم والفطر مع الفدية حتى نسخت الآيةُ التالية ذلك، وذهب ابن عباس إلى أنها محكمة في الشيخ والعجوز العاجزين عن الصوم، وجمع ابن كثير بأن التخيير العام نُسخ وبقيت الرخصة للعاجز."] },
  { id: "tfl-078", s: "tafsir", g: 4, d: 5, t: ["ayat-al-kursi", "divine-attributes", "salaf-views"], src: "al-Ṭabarī, Jāmiʿ al-Bayān, on 2:255; Ibn Kathīr, Tafsīr, on 2:255", v: "2:255", w: 42,
    en: ["Which interpretation of the highlighted word did al-Ṭabarī prefer?", ["Allah's knowledge, following a report from Ibn ʿAbbās", "The ʿArsh itself, as reported from al-Ḥasan al-Baṣrī", "Allah's dominion and sovereignty over creation", "The footstool, the place of the two feet"], "Al-Ṭabarī listed the views and preferred the report from Ibn ʿAbbās that the kursī is Allah's knowledge. Ibn Kathīr held that the sound report from Ibn ʿAbbās is that it is the place of the two feet, and al-Ḥasan said it is the ʿArsh; the question asks only for al-Ṭabarī's preference."],
    de: ["Welche Deutung des hervorgehobenen Wortes bevorzugte al-Ṭabarī?", ["Allahs Wissen, gestützt auf einen Bericht von Ibn ʿAbbās", "Den Thron (ʿArsh) selbst, wie von al-Ḥasan al-Baṣrī berichtet", "Allahs Herrschaft und Souveränität über die Schöpfung", "Den Fußschemel, die Stelle der beiden Füße"], "Al-Ṭabarī führte die Ansichten auf und bevorzugte den Bericht von Ibn ʿAbbās, dass der kursī Allahs Wissen ist. Ibn Kathīr hielt den gesunden Bericht von Ibn ʿAbbās für den, dass er die Stelle der beiden Füße ist, und al-Ḥasan sagte, es sei der ʿArsh; gefragt ist nur nach al-Ṭabarīs Präferenz."],
    ar: ["أيّ تفسير للكلمة المظللة رجّحه الطبري؟", ["علم الله، اعتمادًا على رواية عن ابن عباس", "العرش نفسه كما رُوي عن الحسن البصري", "ملك الله وسلطانه على الخلق", "موضع القدمين"], "ذكر الطبري الأقوال ورجّح الرواية عن ابن عباس أن الكرسي علمه سبحانه، ورأى ابن كثير أن الصحيح عن ابن عباس أنه موضع القدمين، وقال الحسن إنه العرش، والسؤال عن ترجيح الطبري وحده."] },
  { id: "tfl-079", s: "tafsir", g: 4, d: 5, t: ["freedom-of-belief", "abrogation", "salaf-views"], src: "al-Ṭabarī, Jāmiʿ al-Bayān, on 2:256; Ibn Kathīr, Tafsīr, on 2:256", v: "2:256",
    en: ["Which position on the scope of the verse shown did al-Ṭabarī prefer?", ["It is specific to those from whom jizya is accepted, such as the People of the Book, and is not abrogated", "It was abrogated by the later command to fight", "It applies only to the Anṣār children of its occasion", "It applies only to the Arab polytheists of Mecca"], "Al-Ṭabarī reports that some held the verse abrogated and others that it concerns those whose religion may be left to them in return for jizya; he preferred the second. Ibn Kathīr reads it as a general statement: no one should be compelled into Islam, since its truth is evident."],
    de: ["Welche Position zur Reichweite des gezeigten Verses bevorzugte al-Ṭabarī?", ["Er gilt speziell für jene, von denen die Dschizya angenommen wird, etwa die Schriftbesitzer, und ist nicht aufgehoben", "Er wurde durch das spätere Kampfgebot aufgehoben", "Er gilt nur für die Kinder der Anṣār aus seinem Anlass", "Er gilt nur für die arabischen Götzendiener Mekkas"], "Al-Ṭabarī berichtet, dass manche den Vers für aufgehoben hielten und andere ihn auf jene bezogen, die gegen die Dschizya bei ihrer Religion belassen werden; er bevorzugte das Zweite. Ibn Kathīr liest ihn als allgemeine Aussage: Niemand soll zum Islam gezwungen werden, da seine Wahrheit offenkundig ist."],
    ar: ["أيّ قول في نطاق الآية المعروضة رجّحه الطبري؟", ["أنها خاصة فيمن تُقبل منهم الجزية كأهل الكتاب وليست منسوخة", "أنها منسوخة بالأمر بالقتال", "أنها خاصة بأبناء الأنصار الذين نزلت فيهم", "أنها خاصة بمشركي العرب في مكة"], "ذكر الطبري أن من العلماء من قال بنسخها ومنهم من خصّها بمن يُقرّ على دينه بالجزية، ورجّح الثاني، أما ابن كثير فحملها على العموم: لا يُكره أحد على الدخول في الإسلام لأنه بيّن واضح."] },
  { id: "tfl-080", s: "tafsir", g: 4, d: 5, t: ["debt-verse", "legal-rulings-in-tafsir"], src: "al-Qurṭubī, al-Jāmiʿ li-Aḥkām al-Qurʾān, on 2:282", tr: ["jumhur", "comparative"], v: "2:282",
    en: ["Which statement correctly describes the disagreement on the command to write down debts in the verse shown?", ["The majority hold it is a recommendation, while al-Ṭabarī is reported to have held it obligatory", "The majority hold it obligatory, while al-Ṭabarī alone held it a recommendation", "All agree it is obligatory and an unwritten loan is void", "All agree it was abrogated by the following verse on trust"], "Al-Qurṭubī reports that some held writing debts to be an obligation, naming al-Ṭabarī among them, while the majority (jumhūr) see it as a recommendation for securing rights. Others, such as al-Shaʿbī, said it was abrogated by the mention of mutual trust in 2:283, so there is no consensus on abrogation either."],
    de: ["Welche Aussage beschreibt die Meinungsverschiedenheit über das Gebot, Schulden im gezeigten Vers aufzuschreiben, zutreffend?", ["Die Mehrheit hält es für eine Empfehlung, während al-Ṭabarī es für verpflichtend gehalten haben soll", "Die Mehrheit hält es für verpflichtend, nur al-Ṭabarī für eine Empfehlung", "Alle halten es für verpflichtend, und ein unschriftliches Darlehen ist ungültig", "Alle halten es durch den folgenden Vers über das Vertrauen für aufgehoben"], "Al-Qurṭubī berichtet, dass manche das Aufschreiben von Schulden für Pflicht hielten, darunter al-Ṭabarī, während die Mehrheit (jumhūr) darin eine Empfehlung zur Sicherung der Rechte sieht. Andere wie al-Shaʿbī hielten es durch die Erwähnung des gegenseitigen Vertrauens in 2:283 für aufgehoben, sodass auch hierüber kein Konsens besteht."],
    ar: ["أيّ عبارة تصف الخلاف في الأمر بكتابة الدين في الآية المعروضة وصفًا صحيحًا؟", ["الجمهور على أنه للندب، ونُقل عن الطبري أنه للوجوب", "الجمهور على الوجوب، وانفرد الطبري بالندب", "اتفقوا على الوجوب وبطلان القرض غير المكتوب", "اتفقوا على نسخه بآية الأمانة بعده"], "نقل القرطبي أن بعضهم ذهب إلى وجوب كتابة الديون وأنه اختيار الطبري، والجمهور على أنه ندب لحفظ الحقوق، وقال آخرون كالشعبي إنه منسوخ بذكر الائتمان في ٢:٢٨٣، فلا إجماع على النسخ كذلك."] },
  { id: "tfl-081", s: "tafsir", g: 4, d: 4, t: ["end-of-baqara", "abrogation", "hadith-in-tafsir"], src: "Ṣaḥīḥ Muslim, Kitāb al-Īmān (hadith of Abū Hurayra on 2:284–286); Ibn Kathīr, Tafsīr, on 2:284", v: "2:286",
    en: ["According to the hadith of Abū Hurayra in Ṣaḥīḥ Muslim, what did the revelation of the verse shown relieve?", ["The Companions' distress at being held accountable for what is in their souls, as stated in 2:284", "The burden of the night prayer imposed at the start of Sūrat al-Muzzammil", "The strictness of the early fasting rules mentioned in 2:187", "The fear caused by the Jews' objections to the change of qibla"], "When 2:284 was revealed the Companions found it very hard; the Prophet told them to say 'we hear and obey', after which 2:285 was revealed and Allah lifted the burden with 2:286. Many call this naskh, others takhṣīṣ or clarification."],
    de: ["Was erleichterte die Offenbarung des gezeigten Verses nach dem Hadith des Abū Hurayra in Ṣaḥīḥ Muslim?", ["Die Bedrängnis der Gefährten, für das in ihrem Inneren Verborgene zur Rechenschaft gezogen zu werden, wie in 2:284", "Die Last des Nachtgebets vom Beginn von Sūrat al-Muzzammil", "Die Strenge der frühen Fastenregeln aus 2:187", "Die Sorge über die Einwände der Juden gegen die Änderung der Gebetsrichtung"], "Als 2:284 offenbart wurde, fiel es den Gefährten sehr schwer; der Prophet sagte ihnen, sie sollten „wir hören und gehorchen“ sagen, worauf 2:285 offenbart wurde und Allah die Last mit 2:286 aufhob. Viele nennen dies naskh, andere Spezifizierung oder Erläuterung."],
    ar: ["بحسب حديث أبي هريرة في صحيح مسلم، ماذا رفع نزول الآية المعروضة؟", ["ما شقّ على الصحابة من المحاسبة على ما في النفوس المذكورة في ٢:٢٨٤", "عبء قيام الليل المفروض في أول سورة المزمل", "شدّة أحكام الصيام الأولى المذكورة في ٢:١٨٧", "الخوف من اعتراض اليهود على تحويل القبلة"], "لمّا نزلت ٢:٢٨٤ اشتدّ ذلك على الصحابة، فأمرهم النبي ﷺ أن يعلنوا السمع والطاعة، فنزلت ٢:٢٨٥ ورفع الله ذلك بـ٢:٢٨٦، وسمّاه كثيرون نسخًا وسمّاه آخرون تخصيصًا أو بيانًا."] },
  { id: "tfl-082", s: "tafsir", g: 4, d: 5, t: ["muhkam-mutashabih", "waqf-and-meaning", "salaf-views"], src: "Ibn Kathīr, Tafsīr, on 3:7; al-Ṭabarī, Jāmiʿ al-Bayān, on 3:7", v: "3:7",
    en: ["Which statement correctly describes the disagreement about pausing after the name of Allah in the verse shown?", ["Many salaf pause there, so the ultimate reality is known only to Allah; others such as Mujāhid join 'the well-grounded', taking taʾwīl as explanation", "All the salaf continue reading, so the well-grounded know every meaning", "The pause is a matter of melody only and does not affect meaning", "The disagreement is only about whether the verse is Meccan or Medinan"], "Those who pause after the divine name take taʾwīl as the true reality or outcome of things, known only to Allah; those who connect, like Mujāhid and a report from Ibn ʿAbbās, take taʾwīl as tafsīr, which the well-grounded can know. Ibn Kathīr explains that the two readings reflect two meanings of taʾwīl."],
    de: ["Welche Aussage beschreibt die Meinungsverschiedenheit über das Innehalten nach dem Namen Allahs im gezeigten Vers zutreffend?", ["Viele Altvordere halten dort inne, sodass die letzte Wirklichkeit nur Allah kennt; andere wie Mujāhid verbinden mit „den Gefestigten“ und verstehen taʾwīl als Erklärung", "Alle Altvorderen lesen durch, sodass die Gefestigten jede Bedeutung kennen", "Das Innehalten ist nur eine Frage der Melodie ohne Einfluss auf die Bedeutung", "Der Streit betrifft nur, ob der Vers mekkanisch oder medinensisch ist"], "Wer nach dem göttlichen Namen innehält, versteht taʾwīl als die wahre Wirklichkeit oder den Ausgang der Dinge, die nur Allah kennt; wer verbindet, wie Mujāhid und ein Bericht von Ibn ʿAbbās, versteht taʾwīl als tafsīr, das die Gefestigten kennen können. Ibn Kathīr erklärt, dass beide Lesarten zwei Bedeutungen von taʾwīl entsprechen."],
    ar: ["أيّ عبارة تصف الخلاف في الوقف على لفظ الجلالة في الآية المعروضة وصفًا صحيحًا؟", ["يقف كثير من السلف عليه فلا يعلم حقيقة المآل إلا الله، ويصله آخرون كمجاهد بالراسخين حملًا للتأويل على التفسير", "اتفق السلف على الوصل فيعلم الراسخون كل معنى", "الوقف مسألة نغم لا أثر لها في المعنى", "الخلاف إنما هو في كون الآية مكية أو مدنية"], "من وقف على لفظ الجلالة حمل التأويل على حقيقة ما تؤول إليه الأمور وهي مما استأثر الله بعلمه، ومن وصل كمجاهد ورواية عن ابن عباس حمله على التفسير الذي يعلمه الراسخون، وبيّن ابن كثير أن القولين يرجعان إلى معنيين للتأويل."] },
  { id: "tfl-083", s: "tafsir", g: 4, d: 4, t: ["surah-al-nisa", "authority", "salaf-views"], src: "Ibn Kathīr, Tafsīr, on 4:59; al-Ṭabarī, Jāmiʿ al-Bayān, on 4:59", v: "4:59",
    en: ["After reporting that 'those in authority' in the verse shown were explained as rulers by some and as scholars by others, what does Ibn Kathīr conclude?", ["It apparently includes all those in authority, both rulers and scholars", "It refers only to the scholars, and rulers are excluded", "It refers only to the four Rightly Guided Caliphs", "It refers only to commanders of military expeditions"], "Ibn Kathīr notes the occasion reported in al-Bukhārī about a commander of an expedition, and the views of rulers and of scholars, then says the apparent meaning is general to both. Al-Ṭabarī preferred the view that rulers are meant."],
    de: ["Zu welchem Schluss kommt Ibn Kathīr, nachdem er berichtet, dass „die Befehlsgewalt Innehabenden“ im gezeigten Vers teils als Herrscher, teils als Gelehrte erklärt wurden?", ["Gemeint sind offenbar alle mit Befehlsgewalt, Herrscher wie Gelehrte", "Gemeint sind nur die Gelehrten, Herrscher sind ausgenommen", "Gemeint sind nur die vier rechtgeleiteten Kalifen", "Gemeint sind nur die Befehlshaber von Feldzügen"], "Ibn Kathīr erwähnt den bei al-Bukhārī überlieferten Anlass über den Befehlshaber eines Feldzugs sowie die Ansichten zu Herrschern und Gelehrten und sagt, die offensichtliche Bedeutung umfasse beide. Al-Ṭabarī bevorzugte die Ansicht, dass die Herrscher gemeint sind."],
    ar: ["بعد أن ذكر ابن كثير أن أولي الأمر في الآية المعروضة فُسّروا بالأمراء عند بعضهم وبالعلماء عند آخرين، إلامَ انتهى؟", ["أن الظاهر عمومها في كل أولي الأمر من الأمراء والعلماء", "أنهم العلماء فقط دون الأمراء", "أنهم الخلفاء الراشدون الأربعة فقط", "أنهم أمراء السرايا فقط"], "ذكر ابن كثير سبب النزول عند البخاري في أمير سرية، وقولَي الأمراء والعلماء، ثم قال إن الظاهر أنها عامة فيهما، أما الطبري فرجّح أنهم الأمراء."] },
  { id: "tfl-084", s: "tafsir", g: 4, d: 5, t: ["surah-al-araf", "covenant", "salaf-views"], src: "Ibn Kathīr, Tafsīr, on 7:172", v: "7:172",
    en: ["Which statement correctly describes the two main explanations of the covenant taken from the offspring of Ādam in the verse shown?", ["Many hold the offspring were actually brought forth and made to testify, citing reports; others among the salaf and later scholars explain it as the innate disposition (fiṭra) to tawḥīd", "All agree it is a parable only, with no actual event behind it", "All agree it concerns only the sons of Ādam born before his death", "All agree it is the covenant taken from the prophets alone"], "Ibn Kathīr cites reports that Allah brought the offspring from the loins of Ādam and made them testify, and also mentions those among the salaf and khalaf who said the testimony means that they were created upon the fiṭra of tawḥīd. The question asks for the shape of this difference, not a single verdict."],
    de: ["Welche Aussage beschreibt die beiden Haupterklärungen des Bundes, der den Nachkommen Ādams im gezeigten Vers abgenommen wurde, zutreffend?", ["Viele meinen, die Nachkommen seien tatsächlich hervorgebracht und zum Zeugnis gebracht worden, gestützt auf Berichte; andere unter Früheren und Späteren erklären es als angeborene Veranlagung (fiṭra) zum Tawḥīd", "Alle sind sich einig, dass es nur ein Gleichnis ohne tatsächliches Geschehen ist", "Alle sind sich einig, dass es nur die vor Ādams Tod geborenen Söhne betrifft", "Alle sind sich einig, dass es nur der Bund mit den Propheten ist"], "Ibn Kathīr führt Berichte an, wonach Allah die Nachkommen aus den Lenden Ādams hervorbrachte und sie bezeugen ließ, und erwähnt auch Gelehrte unter Früheren und Späteren, die das Zeugnis so verstanden, dass sie auf der fiṭra des Tawḥīd erschaffen wurden. Gefragt ist nach der Gestalt dieser Meinungsverschiedenheit, nicht nach einem einzigen Urteil."],
    ar: ["أيّ عبارة تصف القولين الرئيسين في الميثاق المأخوذ من بني آدم في الآية المعروضة وصفًا صحيحًا؟", ["قال كثيرون إن الذرية أُخرجت حقيقةً وأُشهدت استنادًا إلى روايات، وفسّره آخرون من السلف والخلف بفطرتهم على التوحيد", "اتفقوا على أنه تمثيل محض لا حقيقة له", "اتفقوا على أنه خاص بأبناء آدم المولودين في حياته", "اتفقوا على أنه الميثاق المأخوذ من الأنبياء وحدهم"], "أورد ابن كثير روايات في إخراج الله الذرية من ظهر آدم وإشهادهم، وذكر أن من السلف والخلف من قال إن المراد بهذا الإشهاد فطرهم على التوحيد، والسؤال عن صورة الخلاف لا عن ترجيح واحد."] },
  { id: "tfl-085", s: "tafsir", g: 4, d: 4, t: ["surah-al-tawba", "salaf-views"], src: "Ibn Kathīr, Tafsīr, on 9:108 (hadith of Abū Saʿīd in Ṣaḥīḥ Muslim)", v: "9:108",
    en: ["Which statement correctly describes the views on 'the mosque founded on taqwā from the first day' in the verse shown?", ["Many link the context to Qubāʾ, while a hadith in Ṣaḥīḥ Muslim names the Prophet's Mosque; Ibn Kathīr sees no contradiction, both being founded on taqwā", "All agree it is al-Masjid al-Ḥarām in Mecca", "All agree it is the mosque of Banū Salima, known as al-Qiblatayn", "All agree it is the mosque built at Tabūk during the expedition"], "Qubāʾ fits the context of the masjid al-ḍirār, built nearby, and of people who love to purify themselves; but in Ṣaḥīḥ Muslim the Prophet, when asked, said it was his own mosque in Medina. Ibn Kathīr says that if Qubāʾ is founded on taqwā, the Prophet's Mosque is even more so."],
    de: ["Welche Aussage beschreibt die Ansichten über „die vom ersten Tag an auf Gottesfurcht gegründete Moschee“ im gezeigten Vers zutreffend?", ["Viele beziehen den Zusammenhang auf Qubāʾ, während ein Hadith in Ṣaḥīḥ Muslim die Prophetenmoschee nennt; Ibn Kathīr sieht keinen Widerspruch, da beide auf Gottesfurcht gegründet sind", "Alle sind sich einig, dass es die al-Masjid al-Ḥarām in Mekka ist", "Alle sind sich einig, dass es die Moschee der Banū Salima, bekannt als al-Qiblatayn, ist", "Alle sind sich einig, dass es die während des Feldzugs in Tabūk gebaute Moschee ist"], "Qubāʾ passt zum Zusammenhang der in der Nähe gebauten Moschee al-ḍirār und zu den Menschen, die sich gern reinigen; doch in Ṣaḥīḥ Muslim sagte der Prophet auf Nachfrage, es sei seine eigene Moschee in Medina. Ibn Kathīr sagt, wenn Qubāʾ auf Gottesfurcht gegründet ist, dann die Prophetenmoschee erst recht."],
    ar: ["أيّ عبارة تصف الأقوال في المسجد الذي أُسّس على التقوى من أول يوم في الآية المعروضة وصفًا صحيحًا؟", ["ربط كثيرون السياق بمسجد قباء، وفي صحيح مسلم أن النبي ﷺ عيّن مسجده، ولا تعارض عند ابن كثير لأن كليهما أُسّس على التقوى", "اتفقوا على أنه المسجد الحرام بمكة", "اتفقوا على أنه مسجد بني سلمة المعروف بمسجد القبلتين", "اتفقوا على أنه مسجد بُني بتبوك أثناء الغزوة"], "يناسب قباءٌ سياقَ مسجد الضرار الذي بُني قريبًا منه وذكرَ قوم يحبون التطهر، لكن في صحيح مسلم أن النبي ﷺ سُئل فعيّن مسجده بالمدينة، وقرّر ابن كثير أنه إذا كان قباء مؤسسًا على التقوى فمسجد النبي ﷺ أولى بذلك."] },
  { id: "tfl-086", s: "tafsir", g: 4, d: 4, t: ["surah-al-tawba", "compilation-of-quran"], src: "Jāmiʿ al-Tirmidhī, Abwāb Tafsīr al-Qurʾān, Sūrat al-Tawba; al-Qurṭubī, al-Jāmiʿ li-Aḥkām al-Qurʾān, introduction to Sūrat al-Tawba", v: "9:1",
    en: ["In the report in which Ibn ʿAbbās asks ʿUthmān why no basmala separates al-Anfāl from the surah of the verse shown, what reason does ʿUthmān give?", ["Their content was similar and the Prophet died without making clear whether it belonged to al-Anfāl", "The basmala was lost when the leaves of the copy were damaged", "The Prophet ordered it removed after the expedition of Tabūk", "Zayd ibn Thābit forgot to write it and it was never restored"], "ʿUthmān explained that al-Anfāl was among the early Medinan revelations and Barāʾa among the last, their stories resembled each other, and the Prophet did not clarify the matter, so he placed them together without a basmala. Al-Qurṭubī also reports ʿAlī's explanation that the basmala signals security, while Barāʾa came with its withdrawal."],
    de: ["Welchen Grund nennt ʿUthmān in dem Bericht, in dem Ibn ʿAbbās ihn fragt, warum keine Basmala al-Anfāl von der Sure des gezeigten Verses trennt?", ["Ihr Inhalt war ähnlich, und der Prophet starb, ohne klarzustellen, ob sie zu al-Anfāl gehört", "Die Basmala ging verloren, als die Blätter der Abschrift beschädigt wurden", "Der Prophet befahl nach dem Feldzug von Tabūk, sie zu entfernen", "Zayd ibn Thābit vergaß, sie zu schreiben, und sie wurde nie ergänzt"], "ʿUthmān erklärte, al-Anfāl gehöre zu den frühen medinensischen Offenbarungen und Barāʾa zu den letzten, ihre Inhalte glichen sich, und der Prophet habe es nicht geklärt, daher habe er sie ohne Basmala zusammengestellt. Al-Qurṭubī berichtet auch ʿAlīs Erklärung, die Basmala stehe für Sicherheit, Barāʾa aber sei mit deren Aufhebung gekommen."],
    ar: ["في الخبر الذي سأل فيه ابن عباس عثمانَ عن ترك البسملة بين الأنفال وسورة الآية المعروضة، ما العلة التي ذكرها عثمان؟", ["أن قصتها شبيهة بقصتها وتوفي النبي ﷺ ولم يبيّن أنها منها", "أن البسملة ضاعت لتلف أوراق النسخة", "أن النبي ﷺ أمر بحذفها بعد غزوة تبوك", "أن زيد بن ثابت نسي كتابتها فلم تُستدرك"], "بيّن عثمان أن الأنفال من أوائل ما نزل بالمدينة وبراءة من آخره، وأن قصتيهما متشابهتان ولم يبيّن النبي ﷺ أمرها، فقرن بينهما ولم يكتب البسملة، ونقل القرطبي أيضًا عن علي أن البسملة أمان وبراءة نزلت برفع الأمان."] },
  { id: "tfl-087", s: "tafsir", g: 4, d: 4, t: ["al-isra", "night-journey", "salaf-views"], src: "Ibn Kathīr, Tafsīr, on 17:1; al-Qurṭubī, al-Jāmiʿ li-Aḥkām al-Qurʾān, on 17:1", tr: ["jumhur"], v: "17:1",
    en: ["What is the majority view on the nature of the journey in the verse shown, and which word of the verse do they cite?", ["It was with body and soul while awake, and they cite the word 'His servant'", "It was a vision of the soul in sleep, and they cite the word 'by night'", "It was with the soul only while awake, and they cite the word 'blessed'", "It happened twice in Medina, and they cite the word 'the farthest'"], "The majority hold the Isrāʾ was in body and soul while awake, arguing that ʿabd denotes the whole person and that a mere dream would not have caused Quraysh to deny it. A minority view, based on reports attributed to some early figures, held it was a spiritual vision."],
    de: ["Was ist die Mehrheitsansicht zur Art der Reise im gezeigten Vers, und auf welches Wort des Verses stützt sie sich?", ["Mit Leib und Seele im Wachzustand, gestützt auf das Wort „Sein Diener“", "Eine Schau der Seele im Schlaf, gestützt auf das Wort „bei Nacht“", "Nur mit der Seele im Wachzustand, gestützt auf das Wort „gesegnet“", "Zweimal in Medina, gestützt auf das Wort „die fernste“"], "Die Mehrheit sieht die Isrāʾ als Reise mit Leib und Seele im Wachzustand, weil ʿabd den ganzen Menschen bezeichnet und ein bloßer Traum die Quraysh nicht zum Leugnen veranlasst hätte. Eine Minderheitsansicht, gestützt auf Berichte, die einigen Frühen zugeschrieben werden, hielt sie für eine geistige Schau."],
    ar: ["ما قول الجمهور في صفة الإسراء في الآية المعروضة، وبأيّ لفظ منها استدلوا؟", ["بالجسد والروح يقظةً، واستدلوا بلفظ العبد", "رؤيا روحية في المنام، واستدلوا بلفظ الليل", "بالروح وحدها يقظةً، واستدلوا بلفظ البركة", "وقع مرتين بالمدينة، واستدلوا بلفظ الأقصى"], "الجمهور على أن الإسراء كان بالروح والجسد يقظةً، لأن العبد اسم لمجموع الروح والجسد، ولأنه لو كان منامًا لما استنكرته قريش، وذهب قول مرجوح استنادًا إلى آثار منسوبة إلى بعض المتقدمين إلى أنه رؤيا روحية."] },
  { id: "tfl-088", s: "tafsir", g: 4, d: 5, t: ["al-isra-commandments", "word-meanings"], src: "al-Ṭabarī, Jāmiʿ al-Bayān, on 17:23; al-Qurṭubī, al-Jāmiʿ li-Aḥkām al-Qurʾān, on 17:23", v: "17:23", w: 1,
    en: ["What does the highlighted word mean in this verse, according to the commentators?", ["He commanded and enjoined, not a cosmic decree; Ibn Masʿūd's non-canonical reading has 'enjoined'", "He decreed cosmically, so that none could ever worship other than Him", "He completed and finished the creation of the heavens", "He judged between the disputing parties on the Day of Judgement"], "Ibn ʿAbbās, Mujāhid and others explained qaḍā here as amara or waṣṣā, a legislative command; it cannot be a cosmic decree, since many people do worship others. Al-Qurṭubī notes that the muṣḥaf of Ibn Masʿūd reads 'waṣṣā', which supports this meaning as tafsīr."],
    de: ["Was bedeutet das hervorgehobene Wort in diesem Vers nach den Kommentatoren?", ["Er gebot und trug auf, kein kosmischer Ratschluss; Ibn Masʿūds nicht-kanonische Lesart hat „trug auf“", "Er bestimmte kosmisch, sodass niemand je einen anderen anbeten könnte", "Er vollendete die Erschaffung der Himmel", "Er richtete am Tag des Gerichts zwischen den Streitenden"], "Ibn ʿAbbās, Mujāhid und andere erklärten qaḍā hier als amara oder waṣṣā, also ein gesetzliches Gebot; ein kosmischer Ratschluss kann es nicht sein, da viele Menschen andere anbeten. Al-Qurṭubī bemerkt, dass der Muṣḥaf des Ibn Masʿūd „waṣṣā“ liest, was diese Bedeutung als Erklärung stützt."],
    ar: ["ما معنى الكلمة المظللة في هذه الآية عند المفسرين؟", ["أمر ووصّى، لا القضاء الكوني، وفي قراءة ابن مسعود الشاذة: ووصّى", "قدّر كونًا فلا يعبد أحد غيره أبدًا", "أتمّ خلق السماوات وفرغ منه", "حكم بين المتخاصمين يوم القيامة"], "فسّر ابن عباس ومجاهد وغيرهما القضاء هنا بالأمر والوصية، وهو قضاء شرعي، ولا يصح حمله على القضاء الكوني لأن كثيرًا من الناس يعبدون غير الله، وذكر القرطبي أن في مصحف ابن مسعود: ووصّى، وهي تفسير لهذا المعنى."] },
  { id: "tfl-089", s: "tafsir", g: 4, d: 5, t: ["al-isra-commandments", "mutashabih-al-lafz"], src: "Ibn Kathīr, Tafsīr, on 17:31 and 6:151", v: "17:31",
    en: ["How do commentators explain the difference between the verse shown and 6:151, both forbidding the killing of children because of poverty?", ["6:151 addresses those already poor and mentions the parents' provision first; the verse shown addresses fear of future poverty and mentions the children's provision first", "6:151 addresses fear of future poverty and mentions the children first; the verse shown addresses present poverty and mentions the parents first", "Both address present poverty; the order differs only for the rhyme", "6:151 concerns daughters only, while the verse shown concerns sons only"], "In 6:151 the poverty is already present, so Allah first assures the parents of their own provision; in 17:31 the fear is of poverty to come because of the children, so He first assures the children's provision. This is a classic example of mutashābih al-lafẓ explained by context."],
    de: ["Wie erklären die Kommentatoren den Unterschied zwischen dem gezeigten Vers und 6:151, die beide das Töten von Kindern wegen Armut verbieten?", ["6:151 spricht die bereits Armen an und nennt zuerst die Versorgung der Eltern; der gezeigte Vers spricht die Furcht vor künftiger Armut an und nennt zuerst die Versorgung der Kinder", "6:151 spricht die Furcht vor künftiger Armut an und nennt zuerst die Kinder; der gezeigte Vers spricht gegenwärtige Armut an und nennt zuerst die Eltern", "Beide sprechen gegenwärtige Armut an; die Reihenfolge ändert sich nur wegen des Reims", "6:151 betrifft nur Töchter, der gezeigte Vers nur Söhne"], "In 6:151 ist die Armut bereits da, daher sichert Allah zuerst den Eltern ihre eigene Versorgung zu; in 17:31 besteht die Furcht vor künftiger Armut wegen der Kinder, daher sichert Er zuerst die Versorgung der Kinder zu. Dies ist ein klassisches Beispiel für mutashābih al-lafẓ, das aus dem Zusammenhang erklärt wird."],
    ar: ["كيف يفسّر المفسرون الفرق بين الآية المعروضة و٦:١٥١، وكلتاهما تنهى عن قتل الأولاد بسبب الفقر؟", ["آية الأنعام في فقر واقع فقُدّم فيها رزق الآباء، والآية المعروضة في خشية فقر متوقَّع فقُدّم فيها رزق الأولاد", "آية الأنعام في خشية فقر متوقَّع فقُدّم فيها الأولاد، والآية المعروضة في فقر واقع فقُدّم فيها الآباء", "كلتاهما في فقر واقع، واختلاف الترتيب لمراعاة الفاصلة فقط", "آية الأنعام في البنات خاصة، والآية المعروضة في البنين خاصة"], "في ٦:١٥١ الفقر حاصل فبدأ الله بطمأنة الآباء على رزقهم، وفي ١٧:٣١ الخوف من فقر سيأتي بسبب الأولاد فبدأ برزق الأولاد، وهذا مثال مشهور من المتشابه اللفظي الذي يُفسَّر بالسياق."] },
];
